"""Original English course plans, not translations of private lesson scripts.

This module is authoring code. Published course documents remain private and
must pass their separate content/source/calculation review before promotion.
"""
from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class Lesson:
    title: str
    concept: str
    equation: str
    derivation: tuple[str, str, str]
    challenge: str
    answer: str


@dataclass(frozen=True)
class Course:
    slug: str
    key: str
    title: str
    product: str
    family: str
    ticket: str
    prerequisite: str
    risk: str
    boundary: str
    tool: str | None
    lessons: tuple[Lesson, ...]
    # stem, correct option, four misconception distractors, explanation
    quiz: tuple[tuple[str, str, tuple[str, str, str, str], str], ...]


def L(title, concept, equation, steps, challenge, answer):
    return Lesson(title, concept, equation, tuple(steps), challenge, answer)


VANILLA = Course(
    "vanilla-options-quote", "vanilla_bs", "European options: from contract to quote", "equity vanilla option",
    "vanilla_option_black_scholes", "European call spot 100 strike 100 volatility 20% maturity 1 risk-free rate 5% dividend yield 0%.",
    "Discounted cash flows, logarithms, a normal distribution, differentiation and the distinction between a contractual payoff and a current price.",
    "Spot delta, convexity, implied-volatility risk and carry conventions. A single model price does not include a bid-offer spread or the cost of running a hedge.",
    "European exercise; constant continuous rates, dividend yield and volatility; lognormal diffusion; frictionless continuous hedging. Discrete dividends, American exercise, jumps and executable liquidity need a different treatment.",
    "bs-pricer",
    (
        L("Read the ticket before using the formula", "A European call gives its holder a right at one expiry, not ownership of the underlying throughout the life of the trade. The strike, currency, exercise rule, settlement rule and contract multiplier determine what the number means. A price per share becomes a cash premium only after multiplication by the signed quantity and multiplier. Two tickets with identical spot and strike can still differ through dividends, expiry cut-off or settlement. Record those fields before deciding that two quotes are comparable. Treat an omitted dividend assumption as a missing input, rather than evidence that the issuer pays none.", r"\Phi_T=(S_T-K)^+,\qquad \mathrm{cash\ premium}=n\,m\,C_0", ("List the positive terminal payoff and the states where it is zero.", "Separate the payoff at expiry from the premium paid at inception.", "Apply quantity and contract multiplier only after establishing the unit price."), "A colleague compares a premium per share with a premium for a hundred-share contract. What must be normalised?", "Normalise currency, unit premium, signed number of contracts and contract multiplier. A factor-of-a-hundred cash difference is not a volatility opportunity. Confirm the exercise and settlement terms before investigating market inputs."),
        L("Replicate the convex payoff", "The replication argument prices the claim by constructing a self-financing portfolio, rather than by forecasting its expected physical return. A stock position cancels the instantaneous diffusion term; the remainder must earn the funding rate in the idealised model. Dividend income belongs in the stock holding's financing account. Dynamic rebalancing is essential: a call's delta changes with spot and time. The no-arbitrage conclusion depends on the ability to fund and rebalance the hedge. A real desk therefore treats the clean model price as a reference for managing an imperfect replication, not as a guarantee of realised profit.", r"V_t+(r-q)S V_S+\tfrac12\sigma^2S^2V_{SS}-rV=0", ("Apply Itô's lemma to the option under a diffusion with physical drift.", "Hold minus the option delta in the underlying and include dividend income and funding.", "Eliminate the diffusion term; the physical drift cancels and no arbitrage gives the pricing PDE."), "Why does a bullish expected return fail to enter the clean Black–Scholes call formula?", "The stock return is removed by the replicating hedge under the model assumptions. Risk-neutral drift is fixed by carry. A directional view may motivate a position, but it is not a substitute for no-arbitrage valuation."),
        L("Discount the risk-neutral payoff", "A risk-neutral expectation is a valuation device tied to a numeraire and tradable hedges. It does not state that investors are indifferent to risk. With continuous proportional dividends, the expected terminal stock under the money-market measure grows at the risk-free rate less dividend yield. Discounting the positive terminal payoff separates the asset-or-nothing and cash-or-nothing components. The two normal terms contain different arguments because weighting by the terminal stock changes the distribution used for the stock leg. This distinction explains why replacing both normal terms by one probability gives the wrong premium.", r"C_0=S_0e^{-qT}N(d_1)-Ke^{-rT}N(d_2)", ("Write the discounted expectation of the positive terminal payoff under the pricing measure.", "Split the payoff into the terminal stock times an exercise indicator and strike times that indicator.", "Integrate the lognormal tails; the stock-weighted term produces d1 and the cash term produces d2."), "Which probability enters the discounted strike term, and why is delta different?", "The cash exercise probability in this model is N(d2). Call delta is exp(-qT)N(d1). The stock-weighted expectation and the cash probability are different objects; neither is a general real-world probability of a profitable trade."),
        L("Use parity as a funding control", "Put-call parity follows from matching terminal cash flows, not from assuming any particular volatility. A long call and short put deliver the same terminal value as a prepaid forward less a discounted strike. All legs must share expiry, exercise type, strike and settlement convention. A mismatch may come from a stale quote, a dividend forecast, a borrow constraint or a funding convention rather than an executable arbitrage. For American options, exercise optionality changes equality into bounds. Checking parity before solving for volatility helps distinguish a bad quote from a bad root-finding algorithm.", r"C_0-P_0=S_0e^{-qT}-Ke^{-rT}", ("Subtract the put payoff from the call payoff state by state at expiry.", "Recognise the remaining stock-minus-strike payoff as a forward replication.", "Discount the strike and prepaid stock consistently to obtain parity at inception."), "Both option quotes appear plausible, but their difference violates parity. What do you check first?", "Align timestamps, underlying spot, expiry, dividends, borrow, discounting and exercise rules. Test bid/ask executable inequalities rather than subtracting unrelated mid prices and declaring a risk-free trade."),
        L("Translate sensitivities into a hedge", "Delta is a derivative of unit price with respect to a unit spot move under a stated model. Gamma measures how that delta changes; vega measures sensitivity to volatility expressed either as a decimal or a percentage point. The quote screen and risk system must agree on these units. A long vanilla call has positive option delta, but the signed book delta depends on position size and direction. Neutralising a positive book delta requires selling underlying exposure. The resulting portfolio still carries convexity, volatility, time-decay and discrete-rebalancing risk. Delta neutrality is a local statement, not a maximum-loss certificate.", r"\Delta=e^{-qT}N(d_1),\quad \Gamma=\frac{e^{-qT}\phi(d_1)}{S\sigma\sqrt T},\quad \nu_{1\%}=0.01Se^{-qT}\phi(d_1)\sqrt T", ("Differentiate the unit call price while holding the quoting conventions fixed.", "Scale by signed contracts and multiplier to obtain book exposure.", "Trade the opposite underlying amount, then examine gamma, vega and hedge-rebalancing limits."), "A call is sold rather than bought. Does positive unit call delta imply a positive book delta?", "No. Selling the option reverses its signed risk. Hedge the signed book exposure, not the standalone call label. State whether the hedge is in shares, currency delta or percentage-spot P&L units."),
        L("Separate implied volatility from a forecast", "An implied volatility is the volatility input that makes a chosen model reproduce a market premium. It is conditional on spot, dividends, funding, expiry and exercise conventions. A realised-volatility estimate measures historical path variation under a sampling convention. They need not agree, and their difference alone is not a trading recommendation. An option can be expensive in volatility terms yet cheap relative to another strike after accounting for skew. When quoting, identify the actual market premium or implied quote used, its timestamp and its liquidity. Reusing yesterday's underlying with today's premium may manufacture an apparent volatility move.", r"\sigma_{\mathrm{imp}}:\ C_{BS}(\sigma_{\mathrm{imp}})=C_{\mathrm{mkt}}", ("Check that the market premium lies inside the model's no-arbitrage bounds.", "Keep carry and contractual inputs fixed and solve for a non-negative volatility.", "Reprice the solved volatility and compare the residual with the premium tick size."), "Historical volatility falls while the call's implied volatility rises. Is this inconsistent?", "Not by itself. Realised and implied quantities describe different objects and horizons. Check forward-looking event risk, skew, hedging demand, quote quality and the assumptions of the pricing model."),
        L("Stress the reference price", "A first-order Greek estimate is most useful for a small move around the current state. Larger spot changes alter delta; volatility shocks can interact with spot and time. Compare a Taylor estimate with a complete model repricing and retain the residual. A large residual can signal approximation error, an inconsistent smile rule or an input mismatch. It is not automatically a pricing-model defect. Use the same contract and conventions for both valuations, then change one variable at a time. Only after those controls should a combined stress be interpreted as a picture of the desk's exposure.", r"\Delta C\simeq\Delta\,\Delta S+\tfrac12\Gamma(\Delta S)^2+\nu\,\Delta\sigma+\Theta\,\Delta t", ("Choose signed shocks and put them in the same units as the Greeks.", "Add linear, convexity, volatility and time contributions without double counting.", "Reprice the shocked contract and attribute the difference to higher-order and convention effects."), "Why can a delta-only estimate understate the value change of a long call in a large upward move?", "Positive gamma means delta rises with spot, so the convexity contribution is positive. The approximation is local and says nothing about a simultaneous volatility drop or a change in dividend assumptions."),
        L("Defend a quote in an interview", "A useful answer starts with the contract and ends with a conditional desk action. State a clean reference price, its currency and unit basis, then explain the dominant exposure and the hedge needed for the signed position. Include a control that is independent of pressing the same pricing button again: parity, payoff bounds, a limiting case or a finite difference. Explain what would invalidate the proposed quote, such as an unconfirmed dividend or exercise feature. Acknowledging a model boundary is stronger than supplying an unsupported precision. Commercial spread, capital and funding decisions remain separate from this educational clean valuation.", r"\mathrm{quote\ record}=(\mathrm{ticket},\mathrm{inputs},\mathrm{PV},\mathrm{risk},\mathrm{control},\mathrm{limits})", ("Summarise the reproducible calculation and the assumptions that make it valid.", "Connect signed exposure to an executable hedge size and an independent control.", "Quote conditionally, request missing data or escalate an unsupported feature."), "You have a precise model price but the dividend assumption is unconfirmed. What is the professional response?", "Give a clearly conditional reference and show the dividend sensitivity or relevant bound. Request confirmation before treating it as executable. Extra decimal places do not compensate for an uncertain contractual or carry input."),
    ),
    (
        ("Which quantity is fixed by replication rather than a bullish stock forecast in a European call valuation?", "The risk-neutral carry convention used in the clean price.", ("The actual expected stock return of the buyer.", "The probability that the trade earns a profit after premium.", "The dealer's desired annual investment return.", "A promise that the hedge never loses money."), "Replication removes the physical drift under the model assumptions. It does not remove model risk, trading costs or the uncertainty of realised hedging P&L."),
        ("How should a positive signed call-book delta be neutralised locally?", "Sell the corresponding underlying exposure after applying quantity and multiplier.", ("Buy more underlying because a call has positive delta.", "Sell volatility in exactly the same currency amount.", "Ignore the multiplier because delta is always a percentage.", "Treat the hedge as eliminating gamma and jump risk."), "The hedge has the opposite signed exposure. Gamma, vega, funding and discrete-rebalancing risks remain after initial delta neutralisation."),
        ("What does matching put-call parity control before an implied-volatility solve?", "Consistency of matching option legs, carry and timestamps.", ("The realised future volatility of the stock.", "The physical probability of exercise.", "The absence of every smile arbitrage across maturities.", "An American option's exact early-exercise premium."), "Parity is a cash-flow replication identity for matching European contracts. It is a focused control, not a general guarantee of quote quality."),
        ("Which vega unit conversion is needed when volatility rises by one percentage point?", "Multiply vega per decimal volatility by 0.01.", ("Multiply vega per decimal volatility by 100.", "Multiply gamma by the spot price.", "Use the premium as the volatility shock.", "Use a shock of one full decimal volatility."), "One volatility point is 0.01 in decimal volatility. Mixing the two definitions creates a factor-of-a-hundred P&L error."),
        ("What is the right response to an unconfirmed dividend assumption in a precise call quote?", "State a conditional reference, check carry sensitivity and request confirmation.", ("Set dividends to zero without disclosing it.", "Replace implied volatility with the last realised-volatility estimate.", "Add decimal places to offset the missing input.", "Claim the clean model price is already an executable bid."), "An input uncertainty is a decision constraint. Preserve a conditional, reproducible record and separate it from executable commercial terms."),
    ),
)


GREEKS = Course(
    "options-book-greeks-pnl", "greeks", "Explain an options book's P&L and hedge", "equity options book",
    "options_book_greeks", "Book delta +250k EUR per 1%, gamma -80k EUR per 1%^2, vega +120k EUR per vol point, theta -15k EUR per day. Scenario spot -2%, vol +3.",
    "Taylor expansions, partial derivatives, signed positions and the difference between an absolute spot move and a percentage-spot move.",
    "The book is long delta and vega but short gamma and theta. Offsetting exposures do not remove basis, cross-Greek, liquidity or jump risk.",
    "Local delta-gamma-vega-theta approximation with frozen initial sensitivities. The teaching gamma is quoted per squared percentage-spot move, not per currency-unit spot move. This is an explain, not a full risk-system repricing.",
    "bs-pricer",
    (
        L("Build a risk dictionary", "The same word delta can mean option units, shares, currency exposure or P&L for a one-percent spot move. Gamma can be reported with or without the one-half Taylor coefficient. Vega may mean one decimal volatility or one volatility point. Before adding numbers, define every factor's unit, sign, horizon and aggregation rule. An options book combines positions, so the sign of a total exposure cannot be inferred from the word call or put. A risk dictionary turns the snapshot into a reproducible local model and prevents offsetting two figures that happen to share a screen label.", r"\Delta V\simeq D_{1\%}x+\tfrac12G_{(1\%)^2}x^2+\nu_{\mathrm{pt}}v+\Theta_{\mathrm{day}}d", ("Choose x in percentage-spot points, v in volatility points and d in days.", "Match each sensitivity to the corresponding shock unit.", "Confirm whether the supplied gamma is a second derivative or already a half-gamma P&L coefficient."), "Why is substituting -0.02 into delta per one-percent move wrong for a two-percent decline?", "The shock must be -2 in those units. A decimal return is a different coordinate. Re-express either the sensitivity or the shock before multiplication."),
        L("Explain linear delta P&L", "Delta is the local slope of portfolio value with respect to a chosen underlying coordinate. It captures the first-order directional component, not the whole position's response. Netting exposures is valid only for the same factor and reference convention. A hedge in an index may leave single-stock basis and dividend risk; a futures hedge can add roll and financing effects. A trader needs the sign and the actual hedge instrument, not only the model delta. Preserve the initial snapshot used for explain so that a subsequent intraday hedge is not accidentally treated as if it existed at the beginning of the period.", r"\mathrm{P\&L}_{\Delta}=D_{1\%}\,x", ("Take the signed opening-book exposure in its declared coordinate.", "Apply the signed underlying move over the same explain period.", "Separate opening risk from hedge trades added during that period."), "Does a positive delta mean the option is in the money?", "No. Delta is a derivative and signed portfolio quantity; moneyness compares spot or forward with strike. An out-of-the-money long call can have positive delta."),
        L("Keep the half in gamma", "Gamma adds curvature to the linear approximation. The coefficient is one half because it comes from the second-order Taylor term; squaring the move removes its direction. A short-gamma book therefore loses this local convexity contribution for either a positive or a negative underlying shock, holding other factors fixed. That observation does not imply its total P&L is always negative: premium carry, theta, vega and active hedging matter. For large moves, the initial gamma can change substantially. Full repricing and a hedge-path analysis are necessary before interpreting a single frozen gamma number as a worst-case loss.", r"\mathrm{P\&L}_{\Gamma}=\tfrac12G\,x^2", ("Take the second derivative in exactly the same spot coordinate as x.", "Square the signed move and multiply by one half of gamma.", "Check the symmetry for equal up/down shocks and explain why delta remains asymmetric."), "A book is short gamma and spot rises. Why can gamma still reduce its gain?", "The squared shock is positive, so a negative gamma contributes a negative second-order term. The delta contribution may still be positive; the components must be added with their own signs."),
        L("Explain vega under a smile rule", "A parallel volatility shift is a deliberately simple scenario. Real market surfaces move by strike, maturity and delta, so one net vega number can hide opposite bucket exposures. Sticky strike, sticky delta and model-recalibrated moves are different dynamics. The explain must record which rule holds when spot moves, otherwise the same observed market change can be allocated differently between delta and vega. A volatility-point convention is especially important when aggregating desk reports. Describe the parallel scenario as a sensitivity exercise and retain a separate skew or term-structure stress for concentrations that a single vega total cannot reveal.", r"\mathrm{P\&L}_{\nu}=\nu_{\mathrm{pt}}\,\Delta\sigma_{\mathrm{pt}}", ("Choose a frozen-surface convention and identify the shifted volatility buckets.", "Convert the change into volatility points before multiplying the reported vega.", "Retain smile, term and spot-volatility interaction as separate residual risks."), "Can two large opposite maturity vegas be treated as no volatility risk?", "Their parallel-shift sum may be small, but a term-structure twist can produce a material loss. Keep bucket exposures and inspect the hedge instrument's maturity."),
        L("Put time decay on the right clock", "Theta is a partial derivative with respect to calendar passage under a fixed set of other model inputs. Market systems may report per calendar day or per trading day; financing and realised accrual can be recorded separately. Weekend passage and expiry cut-offs matter, particularly near maturity. A long vanilla option often has negative theta, but portfolio sign and product features prevent a universal statement. The explain should use the opening model convention, state the elapsed interval and distinguish theta from paid coupons, financing cash flows or changes in contractual events. Otherwise a plausible daily number can conceal a double-counted carry item.", r"\mathrm{P\&L}_{\Theta}=\Theta_{\mathrm{day}}\,\Delta d", ("Identify whether the supplied theta is calendar-day or trading-day based.", "Measure the actual elapsed period using that convention.", "Reconcile contractual accrual and financing separately to prevent double counting."), "Why is applying one day's theta across a weekend an assumption?", "The reporting clock may include three calendar days, and near expiry a finite revaluation can differ from a constant-theta extrapolation. State the clock and compare with rolled-date repricing."),
        L("Reconcile explained and actual P&L", "An explain is a bridge between two portfolio valuations plus relevant cash flows and trades. Start with an unchanged opening book, apply market changes under controlled conventions, then account for positions opened or closed during the interval. Define a sign convention for the residual. A residual may reflect cross derivatives, nonlinear revaluation, model recalibration, stale marks, corporate actions or booking errors. It should prompt investigation rather than an automatic attribution to trading skill. Keep the same currency and valuation timestamp across the bridge. Recomputing the opening risk after the move destroys the audit trail and can make an otherwise incorrect explain appear to reconcile.", r"R=\mathrm{P\&L}_{\mathrm{actual}}-\mathrm{P\&L}_{\mathrm{explained}}", ("Sum the signed factor contributions from the preserved opening snapshot.", "Reconcile trades, cash flows, financing and currency translation on a common basis.", "Calculate the residual and investigate material exceptions with a stated tolerance."), "Should a large residual be forced into vega so that the report balances?", "No. Preserve the unexplained amount, verify snapshots and booking, then assess higher-order or convention effects. A mechanically balanced report is not evidence of a correct attribution."),
        L("Design a hedge rather than erase a number", "A hedge should target the loss mechanism and practical constraints, not just drive an aggregate risk cell to zero. Underlying shares address local delta; options are needed to change gamma and vega materially. Hedging one exposure can create another, and bid-offer, liquidity, carry and rebalancing frequency matter. In a short-gamma book, the cost of repeatedly buying after rises and selling after falls explains why realised path variation matters. Test the proposed hedge against a combined stress and bucket-level risks. An interview answer should state what remains after the hedge and which market conditions would require escalation.", r"\mathrm{risk}_{\mathrm{after}}=\mathrm{risk}_{\mathrm{before}}+h\,\mathrm{risk}_{\mathrm{hedge}}", ("Select an actual hedge instrument and its signed risk vector.", "Solve the targeted exposure equation for hedge size, respecting units and liquidity.", "Recompute all other exposures and compare stress loss and execution cost."), "Why does selling underlying fail to neutralise a short-gamma exposure?", "A linear underlying position changes delta but has no option convexity. The initial delta can be neutral while gamma remains negative and the hedge must be rebalanced as spot moves."),
        L("Stress cross effects and data quality", "The omitted terms of a multivariate Taylor expansion include spot-volatility and volatility-convexity effects. They can matter in a large move even if the individual first-order sensitivities look modest. A synthetic stress is a question about consequences, not a probability estimate. State whether rates, dividends, correlation and smile recalibration are held fixed. Stale prices or inconsistent currencies can dominate the model residual, so validate data before adding mathematical complexity. A well-controlled explain includes both a numerical tolerance for approximation error and an operational response when an input cannot be trusted.", r"\Delta V\supset V_{S\sigma}\Delta S\Delta\sigma+\tfrac12V_{\sigma\sigma}(\Delta\sigma)^2", ("Write the mixed terms omitted by the four-Greek approximation.", "Apply a combined stress and compare it with a complete consistent repricing.", "Separate data-quality exceptions from model approximation and escalate each to its owner."), "Is a combined spot-down/vol-up stress implied by a correlation of minus one?", "No. A chosen scenario need not assert any probability or correlation. Describe it as a stress and use a separately validated distribution if a probability or VaR statement is required."),
        L("Deliver the explain memo", "A front-office P&L memo should identify the opening risk, observed shocks, component contributions and remaining unexplained amount. The reader should be able to reconstruct the sign of each term without trusting a coloured dashboard. Explain which inputs are actual observations and which are hypothetical stresses. Propose one hedge or reduction tied to the dominant risk and name the liquidity or model boundary that could prevent it. Distinguish the model explain from accounting P&L or official risk approval. A concise conclusion is valuable only when the underlying calculations and conventions are retained for review.", r"\mathrm{memo}=(\mathrm{snapshot},\mathrm{shocks},\mathrm{components},R,\mathrm{action})", ("Present all components in one currency and horizon.", "State the residual and the independent sign/unit checks performed.", "Choose monitor, hedge, reduce or escalate, explaining the exposure that remains."), "What distinguishes a decision-ready explain from five calculated numbers?", "It connects verified contributions to a signed book, reconciles actual P&L and cash flows, identifies the residual and recommends a conditional action with explicit limitations."),
    ),
    (
        ("With gamma quoted per squared one-percent spot move, which term belongs in a second-order explain?", "One half times gamma times the squared percentage-point shock.", ("Gamma times the unsquared decimal return.", "Gamma times only the sign of the spot move.", "Twice gamma times the squared shock.", "A positive gamma contribution for every short-gamma position."), "The one-half coefficient comes from Taylor's theorem. Risk-coordinate units and the supplied gamma convention must be aligned before applying it."),
        ("A book is delta-neutral but short gamma. What exposure remains?", "Nonlinear spot exposure and the need to rebalance the delta hedge.", ("No exposure to any underlying path.", "A guarantee that realised P&L is zero.", "Only risk-free funding income.", "A positive gamma position created by the underlying hedge."), "A linear hedge removes initial delta, not curvature. Discrete hedging and other factors can still produce material P&L."),
        ("What does a small net vega across two large opposite maturity buckets establish?", "Only a small response to the specified parallel volatility shift.", ("No term-structure volatility risk.", "No short-dated event concentration.", "No bid-offer cost to unwind either position.", "A proof that sticky delta and sticky strike give the same explain."), "Netting under one parallel scenario does not remove exposure to a twist, skew change or mismatch in hedge maturity."),
        ("Which action preserves a trustworthy P&L residual?", "Keep it explicit and reconcile snapshots, cash flows and omitted nonlinear terms.", ("Allocate it to the largest Greek until the report balances.", "Replace the opening risks with closing risks without disclosure.", "Omit intraday hedge trades from the bridge.", "Report it as the trader's skill without investigation."), "A residual is diagnostic information. Reconciliation must retain the original valuation basis and account for actual book changes."),
        ("What must be known before multiplying a daily theta by elapsed time?", "Whether the theta clock is calendar or trading days and what carry is already included.", ("Only whether the option is a call.", "The colour of the daily P&L cell.", "A promise that all long positions have negative theta.", "A volatility-point conversion instead of a time convention."), "Time units and cash-flow accounting determine whether the calculation is comparable and whether financing or accrual is double counted."),
    ),
)

SWAP = Course(
    "rates-swaps-dv01", "swap", "Interest-rate swaps: cash flows, PV and DV01", "EUR fixed-payer interest-rate swap",
    "rates_swap_dv01", "Payer swap EUR notional 100m fixed coupon 3.20% par swap rate 3.00% annuity 4.55, parallel curve rises 10bp.",
    "Discount factors, accrual fractions, basis points and fixed versus floating interest payments.",
    "A fixed-rate payer has positive exposure to a local rise in the par swap rate under a frozen-annuity approximation. Bucketed curve, basis, fixing and collateral risks remain beyond the single DV01 magnitude.",
    "Single-currency fixed-payer/float-receiver teaching swap; supplied annuity in years, frozen for the local PV and parallel-shock calculation. Actual multi-curve valuation needs schedules, forward and collateral discount curves, resets, day counts and settlement conventions.",
    "curve",
    (
        L("Specify the two legs", "An interest-rate swap exchanges cash flows, not the notional principal in a standard same-currency vanilla contract. The fixed leg pays a known coupon times notional and accrual; the floating leg depends on reference fixings and its own accrual convention. Identify whether the position pays or receives fixed before interpreting PV. Payment dates, reset dates, calendars, stubs and collateral affect the valuation. A maturity label and one par rate do not uniquely specify the trade. The simplified ticket deliberately supplies an annuity rather than claiming to reconstruct a full market schedule.", r"CF_i^{\mathrm{fixed}}=NK\alpha_i", ("List fixed and floating payment and fixing dates.", "Apply each leg's contractual accrual fractions and notional.", "Take floating receipts minus fixed payments for a fixed-payer position."), "Does a 100m same-currency swap require exchanging 100m principal at inception?", "Not for the standard vanilla swap in this case. The notional scales interest payments and risk. Collateral and any initial value payment are separate contractual cash movements."),
        L("Build the annuity", "The fixed-leg annuity is the present value of one unit of annual coupon paid across the fixed schedule. It has a time dimension when accrual fractions are measured in years. Multiplying annuity by notional and a decimal coupon produces currency PV. An annuity is not itself the full swap value, and a risky annuity for credit is a different object because survival enters its weights. A full curve shock changes discount factors and may therefore change the annuity. Freezing it is a useful first-order approximation only when that choice is disclosed.", r"A=\sum_i\alpha_iDF_i", ("Compute each fixed coupon's contractual accrual fraction.", "Discount the corresponding payment with the applicable collateral curve.", "Sum discounted accrual weights before applying coupon or notional."), "What is missing if someone calls annuity 4.55 a swap PV of 4.55 EUR?", "The annuity has not yet been multiplied by notional and a coupon difference. It is a valuation weight, not a complete currency price."),
        L("Derive the par fixed rate", "A par rate is the fixed coupon that makes the two legs equal in value for a specific schedule and curve setup. In a single-curve idealisation the floating leg telescopes to a difference of discount factors; this simplification must not be carried unchanged into an arbitrary multi-curve system. The market swap quote depends on tenor, start date and conventions. Par rates can be negative and yield curves can be inverted. These states are not automatically arbitrage or interpolation errors. The control is repricing the actual quoted instruments under a consistent discount/forecast framework.", r"R_{par}=\frac{DF(T_0)-DF(T_n)}{A}\quad\text{(single curve)}", ("Value the floating leg using the single-curve telescoping identity.", "Write fixed-leg PV as notional times fixed coupon times annuity.", "Set the two legs equal and solve for the par coupon."), "Can the telescoping numerator price every collateralised multi-curve swap?", "No. Separate forecast curves can change floating-leg PV while the collateral curve determines discounting. Use the actual projected cash flows and discount factors."),
        L("Value an off-market fixed coupon", "For a fixed-rate payer, receiving the market floating leg and paying an above-market fixed coupon produces a negative value under the local teaching representation. The relevant difference is current par rate less contractual coupon. The position side matters: reversing the swap reverses PV. The fixed coupon does not reset to today's par rate; it remains a contractual cash-flow input. A quoted par rate is a market state used in valuation. Confusing those roles erases the economic value of an existing off-market position and can reverse the conclusion of an interview answer.", r"PV_{payer}\simeq N A(R_{par}-K)", ("Express the floating-leg value using the current par-rate equivalent.", "Subtract the contractual fixed-leg value using the same annuity.", "Apply fixed-payer sign and convert the rate difference into decimal units."), "Why is the example payer swap negative before the upward shock?", "Its contractual fixed coupon exceeds the supplied current par rate. The payer gives up more fixed interest than a newly struck par swap would require, under the stated annuity approximation."),
        L("Convert one basis point into currency", "DV01 often denotes a positive risk magnitude while systems may also report a signed PV change for an upward yield bump. Define which convention is used. In the frozen-annuity par-rate model, one basis point of rate movement is 0.0001 and the fixed payer benefits from an increase. Multiplying a positive magnitude by a signed shock gives the local P&L only after the payer/receiver sign has been set. A whole-curve parallel bump is not the same experiment as shifting one quoted swap rate or one zero-rate node.", r"|DV01|=NA\,10^{-4},\qquad\Delta PV_{payer}\simeq|DV01|\Delta R_{bp}", ("Differentiate the frozen-annuity PV with respect to the decimal par rate.", "Multiply by one basis point to express currency per bp.", "Apply the signed shock and reverse the result for a fixed receiver."), "A report gives a positive DV01 magnitude. Does that identify payer or receiver?", "No. A magnitude alone does not encode side. Ask for the signed upward-bump PV or the actual position, then explain the cash-flow mechanism."),
        L("Distinguish parallel and bucketed hedges", "A single DV01 compresses a vector of curve exposures. Two positions with matching parallel sensitivity can respond differently to a steepener, flattener or basis move. The cash-flow dates determine where the curve matters, while the construction of the curve determines how market-quote bumps propagate. Hedge selection should respect maturity and the actual risk coordinate. A five-year swap and a basket of short futures can match one number without matching every scenario. Reprice the proposed hedge under the same curve construction and retain the residual risk rather than claiming the swap has become risk-free.", r"\Delta PV\simeq\sum_j KRD_j\,\Delta r_j", ("Choose market-quote or zero-node risk coordinates explicitly.", "Bump each coordinate consistently with the curve rebuild convention.", "Match the targeted vector as far as hedge liquidity permits and inspect residual scenarios."), "Why can a DV01-neutral book lose on a curve twist?", "The parallel sum may cancel while individual tenor buckets remain exposed. A twist weights those buckets differently, and basis or convexity may add further P&L."),
        L("Handle fixings, carry and ageing", "A floating coupon that has already fixed is a known cash flow and should not be forecast again from today's curve. Between valuation dates, cash flows occur, accrual changes and the residual maturity shortens. These effects can matter even if quoted rates do not change. Carry and roll depend on the chosen unchanged-market scenario, so explain the convention instead of presenting them as guaranteed income. Reconciliation needs the correct calendar and payment treatment. A local DV01 shock on an unchanged schedule is a different calculation from an overnight roll of the entire trade.", r"PV_{t+\Delta t}=PV(\text{rolled schedule},\text{new fixings},\text{curves})", ("Remove settled payments and retain realised fixings.", "Advance dates under the actual accrual and settlement conventions.", "Separate roll/carry from market-curve P&L in the valuation bridge."), "Should a previously fixed floating coupon change when today's forward curve changes?", "Its contractual fixing remains fixed. Only discounting of that known payment and other unfixed cash flows respond to the relevant market changes."),
        L("Stress the frozen-annuity approximation", "For a large rate move, annuity, projected floating cash flows and curve shape all change. A frozen-annuity estimate is transparent but incomplete. Its useful role is a first sign and scale check against full valuation. Include collateral or forecast-basis stress when the economic contract requires it. Negative rates do not by themselves invalidate discounting; positive discount factors and coherent instrument repricing are the relevant controls. A large discrepancy should be attributed to the approximation or input mismatch before assuming the full engine is wrong.", r"dPV=N A\,dR+N(R-K)\,dA", ("Differentiate both the par rate and annuity in the approximate PV expression.", "Identify the annuity-change term omitted by the frozen-annuity shock.", "Compare a larger full curve rebuild with the local estimate and explain the residual."), "What additional term matters when the annuity moves for an off-market swap?", "The coupon difference times the change in annuity contributes to PV. A full multi-curve repricing may also change floating cash-flow projections and basis exposures."),
        L("Produce a rates desk memo", "The rates memo should name the payer/receiver side, par-rate and coupon conventions, annuity, local PV, risk magnitude and signed shock result. State whether the curve move is parallel and whether annuity was frozen. Explain the hedge in terms of actual maturity and risk coordinates. If the request requires a full valuation, obtain the schedules, fixing history and curve definitions rather than presenting the local approximation as a complete price. An interview panel can assess judgement from the distinction between the verified estimate and the evidence still needed for a tradeable quote.", r"\mathrm{memo}=(PV,|DV01|,\mathrm{shock},\mathrm{side},\mathrm{curve\ basis})", ("Reconcile payer sign and units using the coupon-versus-par relationship.", "Report parallel and important bucketed exposures separately.", "Quote conditionally or escalate missing schedule, fixing or collateral information."), "What information prevents the local swap example from being a full market valuation?", "It does not reconstruct contractual schedules, forecasts, collateral discounting or fixing history. Those are necessary for a production quote and detailed hedge."),
    ),
    (
        ("For the fixed-payer teaching swap, how is the off-market local PV signed?", "It is negative when the contractual coupon exceeds the current par rate.", ("It is always positive because the notional is positive.", "It equals the full notional paid at inception.", "It is zero because every existing swap resets its coupon to par.", "It ignores position side and is identical for a fixed receiver."), "PV is proportional to current par rate minus contractual fixed coupon for this payer representation. Side and a frozen annuity are explicit assumptions."),
        ("What distinguishes a swap annuity from the swap PV?", "Annuity is a discounted accrual weight that still needs notional and a rate difference.", ("Annuity is the notional principal exchanged at inception.", "Annuity is always quoted in currency per basis point.", "Annuity already includes the signed contractual coupon difference.", "Annuity stays invariant under every large curve shock."), "The dimensions matter: annuity times notional times decimal rate produces currency value. Its change matters outside the local frozen-annuity approximation."),
        ("What does equal and opposite parallel DV01 establish for two rates positions?", "Only local cancellation under the specified parallel curve movement.", ("No exposure to a steepener or flattener.", "No forecast-versus-discount basis risk.", "The same response to every node bump.", "No need to retain payment schedules."), "A parallel sensitivity compresses bucket information. Different cash-flow timings and curve coordinates leave twist and basis risk."),
        ("What happens to an already fixed floating coupon after a forward-curve change?", "Its fixing remains known; discounting and other unfixed cash flows may change.", ("Its contractual fixing is replaced by today's par swap rate.", "It becomes a principal exchange.", "Its historical fixing is solved from the current curve.", "It automatically creates a new floating period."), "Do not reforecast a realised fixing. Separate contractual cash-flow knowledge from present-value discounting."),
        ("Which conclusion about negative interest rates is valid for curve controls?", "Negative rates are possible; check positive discount factors, conventions and repricing.", ("Any negative par rate proves arbitrage.", "Any inverted curve proves interpolation failure.", "All discount factors must be below one regardless of rates.", "A negative rate requires deleting the market quote."), "The signs of rates and the curve slope are not universal validity tests. Apply the actual no-arbitrage and instrument-repricing conditions."),
    ),
)


CURVE = Course(
    "yield-curve-bootstrapping", "yield_curve", "Bootstrap a curve and defend its forwards", "single-curve annual-pay interest-rate curve",
    "yield_curve_bootstrap", "Bootstrap annual par swaps: 1 year 3.00%, 2 years 3.20%, 3 years 3.35%.",
    "Discounting, cash-flow schedules, simple versus continuous compounding and solving a linear equation.",
    "A fitted pillar quote does not establish interpolation quality, forward plausibility or correct collateral/forecast conventions. Quote sensitivities depend on the entire construction rule.",
    "Annual-pay regular par swaps under a single-curve teaching convention, unit accruals at supplied maturities. No claim of a production OIS/IBOR multi-curve calibration, holiday-calendar support or live market quotes.",
    "curve",
    (
        L("Define the curve's economic role", "A discount curve maps payment dates to present-value weights in a stated currency and collateral framework. A forecast curve maps index periods to projected floating rates. The two can coincide in a single-curve teaching model but should not be confused in a collateralised multi-curve setup. A curve label is not a convention. Record currency, index, collateral, as-of time, day count and instrument definitions. One set of observed par rates can generate different intermediate forwards under different interpolation choices, so the curve-building algorithm is part of the valuation specification.", r"PV=\sum_i CF_iDF(0,T_i)", ("Identify the cash-flow currency and discounting framework.", "Match quoted calibration instruments to their actual schedules.", "Separate discount weights from forecast quantities unless the single-curve assumption is explicit."), "Can a curve named EUR automatically serve as every EUR forecast and discount curve?", "No. Currency alone does not identify collateral, index or forecasting conventions. State the intended cash flows and construction basis."),
        L("Solve the first discount factor", "An annual one-period par swap has a fixed coupon and a floating leg consistent with the single-curve funding identity. With unit accrual, its equation gives the first discount factor directly. Rates must be decimals inside the expression. A discount factor is dimensionless and positive; it need not always be less than one when rates can be negative. The simple first pillar is a valuable control because it can be computed by hand without an optimisation engine. That control fails if an actual instrument has a different accrual fraction or settlement date than the teaching assumption.", r"DF_1=\frac{1}{1+s_1\alpha_1}", ("Write fixed coupon PV equal to one minus the terminal discount factor.", "Collect the terminal discount-factor terms on one side.", "Divide by one plus rate times accrual and verify the instrument reprices."), "Why is 3 rather than 0.03 an invalid internal representation of a three-percent rate?", "It changes the denominator by two orders of magnitude and therefore the implied discounting. Input format and annualisation must be normalised before solving."),
        L("Bootstrap subsequent pillars", "Bootstrapping solves later discount factors using cash flows whose earlier discount weights are already known. For annual par swaps, subtract the PV of previous fixed coupons from par and divide by the final coupon-plus-principal coefficient. This triangular structure is what makes the recursion transparent. Irregular schedules or missing intermediate pillars can require interpolation inside calibration; pretending those cash flows do not exist changes the instrument. The procedure should preserve the quote set, schedule and residual at every pillar. Solving a curve is not complete until its original instruments reprice within a justified tolerance.", r"DF_n=\frac{1-s_n\sum_{i<n}\alpha_iDF_i}{1+s_n\alpha_n}", ("Value earlier fixed coupons with the discount factors already solved.", "Isolate the final cash-flow coefficient including the par redemption identity.", "Solve the remaining discount factor and reprice the complete instrument."), "Why does the two-year par rate not equal the two-year zero rate?", "The par rate prices coupons at multiple dates, while the zero rate describes one terminal payment. Their relationship uses the entire earlier discount curve."),
        L("Translate discount factors into zero rates", "A zero rate is a representation of a discount factor under a chosen compounding convention. Continuous and annually compounded zero rates can differ numerically while representing the same present-value weight. A chart must label the convention and maturity basis. Comparing an annual par quote directly with a continuous zero rate can create a spurious discrepancy. Negative zero rates are mathematically compatible with discount factors above one. What matters is a coherent pricing framework and the actual market context, not an assumption that every rate must be positive.", r"z_c(T)=-\frac{\log DF(T)}{T},\qquad z_a(T)=DF(T)^{-1/T}-1", ("Start from the same positive discount factor.", "Invert the continuous or annual compounding relation for the stated maturity.", "Reconstruct the discount factor from either representation to verify equivalence."), "Two zero-rate screens differ although they imply the same discount factor. What can explain it?", "Different compounding or time conventions can produce different displayed rates without any pricing disagreement. Normalise the representation before comparing."),
        L("Derive interval forward rates", "A forward rate describes the relative value of payments across two dates. Continuous and simple annualised forwards use different transformations of the same discount-factor ratio. A high three-year zero rate is not itself the rate for borrowing between years two and three. The interval length and accrual convention must be explicit. A market-implied forward is not an unbiased forecast of the future realised spot rate: risk premia, collateral and model conventions matter. Forward curves often reveal interpolation behaviour more sharply than a smooth-looking zero-rate chart.", r"f_c(t_i,t_j)=\frac{\log(DF_i/DF_j)}{t_j-t_i},\qquad F_s=\frac{DF_i/DF_j-1}{\alpha_{ij}}", ("Form the discount-factor ratio linking the two dates.", "Convert the ratio into the chosen continuous or simple rate.", "Reinsert the rate into the corresponding compounding relation and recover the ratio."), "Does a forward above today's short rate guarantee the future realised short rate is higher?", "No. It is a market-implied valuation quantity conditional on conventions, not a guarantee or an unbiased physical forecast."),
        L("Choose interpolation deliberately", "A curve must value dates between calibration pillars. Interpolating rates, log discount factors or forwards produces different intermediate behaviour even when all original quotes fit. Log-linear discount interpolation gives piecewise constant continuous forwards; smoothness of a zero chart alone does not establish acceptable forward dynamics. Record the rule, extrapolation policy and any constraints. Inspect changes near sparse tenors and at the boundary of the calibrated domain. A numerical artefact can create an artificial hedge concentration even while every pillar's residual is tiny.", r"\log DF(t)=(1-w)\log DF(t_i)+w\log DF(t_j)", ("Locate the two surrounding pillar times and compute the interpolation weight.", "Interpolate the selected representation, here log discount factors.", "Recover the discount factor and inspect the implied interval forward and sensitivity."), "Why does perfect repricing at pillars fail to prove a safe extrapolation beyond the last tenor?", "No quoted instrument constrains that region. The extrapolation is an additional model assumption and can materially alter long-dated values and risks."),
        L("Validate fit, shape and units separately", "Instrument repricing, positive discount factors and forward diagnostics are complementary controls. A tiny calibration residual can coexist with an unrealistic schedule or wrong quote units if both calibration and validation repeat the same mistake. A downward-sloping curve or negative forward is not automatically invalid; investigate its economic plausibility, quote source and construction assumptions. Inspect absolute forward magnitudes and local jumps rather than imposing a universal slope. Preserve rejected inputs and diagnostics so the decision can be reviewed instead of silently deleting quotes to improve the fit.", r"\varepsilon_j=PV_j(\mathrm{curve})-PV_j^{\mathrm{market}}", ("Reprice every original instrument under the declared conventions.", "Inspect positive finite discount factors and intermediate forward behaviour.", "Investigate outliers using independent schedule and unit checks, retaining the exception record."), "What is wrong with deleting all inverted sections to make the curve look normal?", "Inversion can be legitimate. Altering quotes for visual shape discards market information and conceals the actual construction or data-quality issue."),
        L("Measure sensitivity through a rebuild", "A market-quote bump changes a calibrated curve, not merely one displayed zero rate. Rebuild the curve consistently after perturbing one quote, then reprice the target cash flows. This reveals how the construction spreads risk across tenors. A zero-node bump is a different coordinate and may be useful, but it should be named. Hedge ratios are meaningful only when the risk and hedge instrument use compatible coordinates. An unchanged parallel DV01 does not establish stable curve risk if the interpolation rule or calibration instrument set has changed.", r"\mathrm{quote\ risk}_j\simeq\frac{V(q_j+h)-V(q_j-h)}{2h}", ("Perturb one market quote with a clearly stated decimal or bp bump.", "Rebuild the complete curve under the identical calibration algorithm.", "Revalue the target and hedge, then compare the resulting quote-risk vectors."), "Why is bumping a zero node different from bumping a par swap quote?", "A par quote maps through calibration to multiple discount factors. The risk coordinates and hedge interpretation therefore differ."),
        L("Handoff a reproducible curve", "A curve handoff includes the quote snapshot, as-of time, conventions, instruments, interpolation and extrapolation policies, residuals and diagnostics. Mark synthetic teaching quotes as synthetic. An available curve is not necessarily an appropriate curve for the next product or collateral agreement. State which valuations it supports and which require another forecast or discounting framework. A desk user should be able to recreate both the curve and a simple instrument value from the record, then see what changes when a quote or convention changes.", r"\mathrm{curve\ record}=(q,\mathrm{schedules},\mathrm{rules},DF,\varepsilon,\mathrm{risk})", ("Preserve the original quotes and normalised instrument definitions.", "Attach construction rules, repricing residuals and forward diagnostics.", "Name supported use cases and escalate a mismatched currency, index or collateral request."), "What makes an exported list of zero rates insufficient for reproducing a desk curve?", "It omits the calibration instruments, cash-flow conventions, interpolation and extrapolation policies, and quote-risk construction. Those choices affect values and hedges."),
    ),
    (
        ("Why do a par swap rate and a zero rate for the same final maturity generally differ?", "The par rate weights coupons across dates while the zero rate represents one terminal cash flow.", ("A zero rate always excludes discounting.", "A par rate is the realised future overnight rate.", "The two rates must be identical in every single-curve model.", "A difference proves a negative-rate arbitrage."), "Coupon timing matters. Earlier discount factors enter the par-rate equation, while a zero rate is a compounding representation of one discount factor."),
        ("Which information must be retained to reproduce an intermediate forward?", "Discount factors, the exact interval, accrual/compounding and interpolation rules.", ("Only the final maturity's par rate.", "Only the slope colour of a zero-rate chart.", "A guarantee that all rates are positive.", "A historical average return on the underlying."), "The forward is derived from a discount-factor ratio over a defined interval. Its display and intermediate shape depend on construction conventions."),
        ("What does perfect pillar-instrument repricing establish?", "Fit to those instruments under the declared construction and conventions.", ("Correct extrapolation at every unquoted maturity.", "A guarantee of unbiased forecasts of future rates.", "No possible calendar or schedule mistake.", "The absence of interpolation model risk."), "A fit check is necessary but local to the quoted instruments. Independent convention, shape and boundary checks remain necessary."),
        ("Which observation is not automatically a curve error?", "A negative rate or an inverted term structure.", ("A non-finite discount factor.", "A residual far outside the stated quote tolerance.", "Mixing decimal rates with percentage inputs without conversion.", "Using a forecast curve as collateral discounting without justification."), "Negative rates and inversion can be economically coherent. Validate discount factors, schedules, fit and intended curve use rather than imposing a universal shape."),
        ("Why must quote-based risk rebuild the curve after the bump?", "The perturbed calibration quote can affect several discount factors and target cash flows.", ("A par quote and a zero node are always the same risk coordinate.", "Rebuilding forces all rates to become positive.", "Only the original quote's final payment can ever change.", "The target value is independent of interpolation."), "Calibration maps market quotes into a full valuation curve. Consistent bump-and-rebuild risk reflects that mapping and its construction rules."),
    ),
)


BOND = Course(
    "fixed-income-bonds-duration", "bond", "Fixed-rate bonds: price, duration and convexity", "long fixed-rate bullet bond",
    "bond_duration_dv01", "Bond market value 50m modified duration 6.2, yield rises 25bp.",
    "Present values, coupon schedules, yield compounding, derivatives and basis points.",
    "A long option-free bond loses value when its yield rises. Modified duration is a local yield sensitivity; convexity improves but does not make a finite-shock approximation exact. Credit, liquidity and curve-shape exposures remain.",
    "The local risk ticket supplies market value and modified duration, not a cash-flow schedule. Its output is a first-order yield-shock estimate. The separate canonical bond tool supports regular unadjusted fixed-rate bullet schedules and exact yield repricing, not callable bonds, OAS or credit events.",
    "bond",
    (
        L("Separate a price quote from settlement cash", "A fixed-rate bond promises scheduled coupons and principal, subject to the issuer's contractual obligations and credit risk. Market convention often quotes a clean price per 100 nominal while settlement uses the dirty price including accrued interest. A price of 101 is not a cash amount until the notional basis is applied. Determine settlement date, coupon frequency, day count and maturity before computing accrued interest or yield. The first-order risk ticket in this course supplies market value directly, so it must not be silently relabelled as nominal principal in a more detailed price calculation.", r"P_{dirty}=P_{clean}+AI,\qquad\mathrm{cash}=P_{dirty}\frac{N}{100}", ("Construct the coupon period around settlement.", "Compute accrued interest using the stated day-count convention.", "Add accrued to the clean quote and scale by nominal divided by 100."), "Why can two clean-price quotes hide different settlement cash amounts?", "Accrued interest, settlement date, currency and nominal basis may differ. Compare dirty amounts on a consistent schedule before declaring a price discrepancy."),
        L("Discount the contractual schedule", "A yield-to-maturity price discounts every promised payment using a single yield with a specified coupon-frequency convention. It is a compact quote representation, not a complete term-structure or credit model. Payment dates strictly after settlement determine which cash flows remain. Irregular stubs, ex-coupon periods and holiday adjustments require additional conventions beyond the regular teaching engine. Preserve the schedule and coupon amounts so a hand cash-flow sum can validate the compact price. A high coupon is not itself evidence of a high expected return if the market price is correspondingly above par.", r"P(y)=\sum_i\frac{CF_i}{(1+y/m)^{m t_i}}", ("List remaining coupon and principal cash flows with payment times.", "Apply yield compounding at coupon frequency consistently.", "Sum discounted payments to obtain dirty value before subtracting accrued interest."), "Does a higher coupon necessarily give the buyer a higher yield?", "No. The price paid and remaining cash-flow schedule determine yield. A high-coupon bond can trade at a premium with the same yield as a lower-coupon bond."),
        L("Interpret and invert yield", "Yield is the rate that makes the present value of the remaining promised cash flows equal the observed dirty price under the chosen convention. It is not a guaranteed realised holding-period return. Reinvestment, sale price, default, taxes and financing can make realised outcomes differ. A root solve should retain a supported rate domain and repricing residual. An apparently converged yield can still be wrong if the clean price was used as dirty or the schedule was mis-specified. Negative yields are possible within a valid domain; the denominator and compounding assumptions must remain well defined.", r"P(y^*)-P_{dirty}^{market}=0", ("Convert the quoted clean price into the proper dirty target.", "Solve the cash-flow pricing equation inside a valid yield bracket.", "Reprice the solved yield and compare the residual with price precision."), "Why is yield-to-maturity not a guaranteed holding-period return?", "It summarises a promised cash-flow price under a convention. Reinvestment rates, early sale prices, credit events and costs can differ from that representation."),
        L("Derive modified duration", "Macaulay duration is a present-value-weighted average payment time. Modified duration converts that timing measure into the local proportional price response to a change in quoted yield. Coupon-frequency conventions matter in the conversion. For a long ordinary positive-cash-flow bond, modified duration is positive while the signed price derivative with respect to yield is negative. A zero-coupon bond provides a useful timing check, but its modified duration still depends on yield compounding. The supplied duration in the local example is modified duration; treating it as Macaulay duration would require a conversion before using it in the shock formula.", r"D_{mod}=-\frac{1}{P}\frac{\partial P}{\partial y},\qquad\frac{\Delta P}{P}\simeq-D_{mod}\Delta y", ("Differentiate each discounted cash flow with respect to quoted yield.", "Sum the negative price derivative and divide by current dirty value.", "Use a decimal yield shock and reverse the sign for a short position."), "Does a duration of 6.2 mean the bond matures in exactly 6.2 years?", "No. It measures price sensitivity under a yield convention. Cash-flow timing, coupon structure and yield determine it; contractual maturity is a separate date."),
        L("Convert duration into DV01", "Multiplying market value by modified duration and one basis point gives a first-order currency sensitivity magnitude. The market-value basis is essential: multiplying a nominal amount by duration without accounting for price can misstate the cash exposure. A long bond's upward-yield P&L is negative even if the reported DV01 is a positive magnitude. A central finite-difference DV01 from full repricing is a useful independent check. Keep the one-basis-point magnitude distinct from an actual multi-basis-point stress and from bucketed curve risk.", r"|DV01|\simeq V D_{mod}10^{-4}", ("Use the signed position's current market value on a consistent price basis.", "Multiply modified duration by one decimal basis point.", "Attach currency per bp, then apply the shock direction to obtain P&L."), "What changes if the price is per 100 but the notional is in currency units?", "Scale the price by notional divided by 100 to obtain market value before using duration. Do not multiply both a per-100 price and a full currency amount without normalisation."),
        L("Add convexity and assess approximation error", "For an option-free bond with positive cash flows, positive convexity makes the price-yield relationship curve above its tangent. A duration-only estimate overstates the loss for a yield rise and understates the gain for a yield fall, locally. The second-order term is positive for either direction of the shock. This statement does not transfer unchanged to callable or other option-embedded bonds. A duration-convexity approximation remains local; compare it with exact repricing for a large shock and identify the remaining higher-order error rather than declaring it exact.", r"\frac{\Delta P}{P}\simeq-D_{mod}\Delta y+\tfrac12Cx(\Delta y)^2", ("Differentiate the price-yield relation twice and normalise by price.", "Add one half of convexity times the squared decimal yield shock.", "Compare duration-only and duration-convexity estimates with full schedule repricing."), "For a positive-convexity long bond, does omitting convexity understate the loss from a yield rise?", "No. The positive second-order contribution offsets part of the duration loss, so duration-only overstates that loss locally. Callable-bond behaviour requires another analysis."),
        L("Distinguish yield risk from credit and curve risk", "A single yield shock combines effects that an actual risk system may separate into reference-curve, spread and liquidity components. Different maturities can respond differently to a curve twist even when a duration total is matched. Credit deterioration may change both promised-cash-flow valuation and the economic expectation of repayment. A government-bond hedge can reduce rates sensitivity while leaving credit spread risk. The teaching engine does not model default or recovery, so its exact yield repricing is exact only for its promised cash flows and yield convention, not an exact account of every realised market move.", r"\Delta V\simeq\Delta V_{rates}+\Delta V_{spread}+\mathrm{residual}", ("Identify the market factors represented by the quoted yield change.", "Separate reference-rate and spread exposures where the data and model permit.", "Choose compatible hedges and state the credit, liquidity and basis risks left behind."), "Can a duration-matched government-bond hedge remove a corporate bond's default risk?", "No. It may address part of rates exposure but does not replicate issuer default, recovery or liquidity. Keep those mechanisms explicit."),
        L("Deliver a bond decision with a price basis", "A useful bond answer states nominal versus market value, clean versus dirty price, settlement and yield conventions, modified duration, DV01 and the signed shock result. If convexity is supplied, show its contribution and compare against full repricing. If it is not supplied, do not invent a second-order correction. Explain which hedge targets the identified exposure and which risks remain. For a full quote, obtain the actual schedule and settlement conventions; for the supplied local risk case, label the result as a first-order estimate rather than a reconstructed bond price.", r"\mathrm{record}=(\mathrm{price\ basis},V,D_{mod},DV01,\Delta y,\Delta V)", ("Reconcile price and market-value units before reporting risk.", "State first-order versus exact repricing and any convexity contribution.", "Recommend a conditional hedge or escalation tied to the actual rates/credit exposure."), "Can the local duration ticket determine the exact clean price and YTM?", "No. It lacks the cash-flow schedule and settlement conventions. Its market-value and duration inputs support a local risk estimate, not a unique price/yield inversion."),
    ),
    (
        ("Which value belongs in the local currency DV01 formula with modified duration?", "Current market value on the stated price basis.", ("Always nominal principal regardless of price.", "Accrued interest alone.", "The coupon rate expressed as a currency amount.", "The number of remaining coupon dates without cash-flow weights."), "DV01 scales proportional price sensitivity by the current monetary exposure. Normalise per-100 quotes before multiplying."),
        ("For an option-free long bond with positive convexity, what does duration-only do for a yield rise?", "It locally overstates the loss because the convexity correction is positive.", ("It always understates the loss.", "It becomes an exact finite-shock reprice.", "It implies negative convexity for every coupon bond.", "It eliminates the need to specify a decimal yield shock."), "The squared-shock convexity term offsets some of the negative duration term. This statement depends on the positive-convexity option-free setting."),
        ("What is the relation between clean price, accrued interest and settlement value?", "Dirty price equals clean price plus accrued interest before nominal scaling.", ("Clean price always equals settlement cash.", "Accrued interest must be added twice for semiannual coupons.", "Dirty price excludes all coupon entitlement.", "A per-100 clean quote is already a full notional currency amount."), "Accrued interest and the per-100 convention determine settlement cash. Use the actual settlement date and day count."),
        ("Which statement about YTM is correct?", "It is a promised-cash-flow pricing rate under a convention, not a guaranteed realised return.", ("It guarantees the next holding-period return.", "It contains a complete default and recovery model.", "It does not depend on settlement or coupon timing.", "It is identical to every maturity's discount-curve zero rate."), "Reinvestment, sale price, costs and credit events can change realised outcomes. Yield is a compact price representation."),
        ("What remains after matching a corporate bond's rates duration with a government bond?", "Credit-spread, issuer-default, liquidity and hedge-basis risks can remain.", ("All possible loss is eliminated.", "The corporate issuer becomes government guaranteed.", "The two cash-flow schedules become identical.", "A single yield model now prices recovery exactly."), "A rates hedge is not a replication of issuer credit risk. Keep the risk mechanism and the model boundary separate."),
    ),
)

SMILE = Course(
    "implied-volatility-smile", "vol_smile", "Implied volatility: inversion, smile and quote controls", "European equity-index option smile",
    "implied_vol_smile", "European call spot 100 strike 100 maturity 1 risk-free rate 5% dividend yield 0% market price 10.4506, find implied volatility.",
    "European option payoffs, Black–Scholes, forward carry, derivatives and numerical root finding.",
    "Low-vega inversion, stale quotes, skew/term concentrations and surface dynamics. A good numerical fit can still contain static arbitrage or use inconsistent market conventions.",
    "The worked calculation inverts one European-call premium under flat carry and a Black–Scholes quoting convention. It does not calibrate an arbitrage-free full surface or determine future realised volatility. Surface examples are synthetic, not executable market quotes.",
    "volsurface",
    (
        L("Normalise the quote before inversion", "An implied-volatility input is conditional on the premium's contract, strike, expiry, exercise rule, underlying reference and carry. A premium in index points cannot be compared directly with a cash premium for many contracts. Bid, ask and midpoint are different observations. Match timestamps before solving: an unchanged premium and a changed underlying can create a different implied volatility without a new option quote. Preserve the original observation, then normalise it into the model's unit price. A root solver cannot repair an inconsistent quote merely by finding a precise answer.", r"C_{model}(S,K,T,r,q,\sigma)=C_{market}", ("Align contract, unit basis, underlying, timestamps and carry.", "Choose whether the target is bid, ask or midpoint.", "Solve only after the target represents the same economic payoff as the model."), "What can produce a spurious volatility change when the option screen is stale?", "A fresh spot combined with an old premium changes the model inversion. Align observations and keep the original timestamps before interpreting the result as a market repricing."),
        L("Check bounds and root existence", "For a European call with the stated continuous-carry model, the premium lies between discounted intrinsic value and the prepaid underlying. A quote outside these bounds has no admissible implied volatility under that contract representation. At a boundary, the root can be degenerate or poorly identified; zero maturity requires a payoff treatment. Tolerance should reflect the quote's precision and tick size. Rejecting an impossible premium is a useful output, not an excuse to clamp the quote silently or substitute a convenient volatility.", r"\max(Se^{-qT}-Ke^{-rT},0)\le C\le Se^{-qT}", ("Derive the lower bound from payoff dominance and parity.", "Bound the call by the prepaid underlying value.", "Test the observed target and numerical domain before starting the solve."), "What should an inversion do with a premium above the prepaid underlying?", "Reject the inconsistent target under the declared European model and check contract or data. A larger volatility cannot make an inadmissible quote valid."),
        L("Use vega to understand conditioning", "Vega measures how much the model premium changes when its volatility input moves. If vega is very small, a tiny premium error can imply a large volatility error. Deep wings and near-expiry contracts can be especially poorly conditioned. Report both the premium residual and the relevant scale rather than trusting a visually stable volatility digit. A bid-offer spread can be mapped into a wide implied-volatility interval, but a midpoint inversion alone hides that uncertainty. The mathematical conditioning is separate from whether the option is economically liquid enough to trade.", r"\delta\sigma\simeq\frac{\delta C}{\nu}", ("Linearise model premium with respect to decimal volatility.", "Invert the local slope to estimate sensitivity of the root to premium error.", "Inspect low-vega regions and compare uncertainty with the requested quote precision."), "Why can a one-cent quote change create a large wing-volatility move?", "The premium may be locally insensitive to volatility, so the inverse problem amplifies the quote error. The move need not imply a comparable change in economically meaningful risk."),
        L("Combine Newton speed with a bracket", "Newton's method divides the price residual by vega. It can converge quickly near a well-conditioned root but jump outside the positive-volatility domain when vega is small or the initial guess is poor. A bracketed method uses monotonicity to maintain an admissible interval. A practical hybrid accepts a Newton step only when it remains inside the bracket, otherwise it bisects. Stop on premium residual and bracket width according to a documented rule. Repricing the solved volatility is part of the result, not an optional cosmetic check.", r"\sigma_{n+1}=\sigma_n-\frac{C(\sigma_n)-C_{market}}{\nu(\sigma_n)}", ("Establish a valid volatility bracket around an admissible price target.", "Take a Newton step only when vega and the proposed step are safe.", "Update the bracket, fall back to bisection and verify the premium residual."), "Does a small change in successive volatility iterates prove the option is correctly repriced?", "No. An iteration can stagnate while retaining a material premium error. Check repricing residual, domain and the actual contract conventions."),
        L("Represent a smile in forward coordinates", "Log-forward moneyness separates strike from spot carry and makes cross-expiry comparisons clearer. A smile is an implied-volatility pattern across strike at a given expiry, not a claim that volatility predicts the direction of the underlying. Quotes in delta space add another model convention because delta itself depends on volatility and carry. Record whether the surface uses strike, forward moneyness or a specific delta definition. A surface assembled from inconsistent coordinate conversions can look smooth while interpolating different economic points.", r"k=\log(K/F),\qquad F=Se^{(r-q)T},\qquad w(k,T)=\sigma_{imp}^2(k,T)T", ("Compute the forward consistently with the premium's carry assumptions.", "Convert strike into log-forward moneyness.", "Use total variance when comparing maturity structure, retaining the original strike mapping."), "Why should a delta-quoted smile specify its delta definition?", "Spot/forward and premium-adjusted deltas can map the same numerical delta to different strikes. The quote coordinate must be reproducible before interpolation."),
        L("Check static arbitrage through prices", "A fitted volatility curve is not automatically an arbitrage-free option-price curve. At a fixed expiry, European call prices should decrease and be convex in strike under matching conventions. Across expiries, calendar comparisons require consistent forwards, discounting and a stated underlying/carry framework. Smooth total variance is useful but not a universal substitute for price-space checks. Sparse or crossed bid-ask data require a transparent cleaning policy. Preserve original quotes and explain exclusions instead of silently changing observations until the surface looks attractive.", r"\partial_K C\le0,\qquad\partial_{KK}C\ge0", ("Convert fitted volatilities back into matching European call premiums.", "Check vertical-spread monotonicity and butterfly convexity across strike.", "Apply maturity checks only after aligning forward and discounting conventions."), "Can a low least-squares fitting error certify no butterfly arbitrage?", "No. The objective may not impose convexity of call prices. Inspect or constrain the implied price surface independently."),
        L("Interpret SVI parameters and limits", "SVI describes total implied variance as a function of log-moneyness. Its parameters control level, wing behaviour, skew, horizontal shift and curvature. Parameter admissibility and nonnegative variance are necessary but not sufficient to establish every no-arbitrage condition. Calibration is sensitive to sparse wings, weights and bid-offer uncertainty. A parameter change is not itself a trade unless it maps into a priced and hedged exposure. Compare fits in premium space as well as volatility space and state how the fitted slice is connected to neighbouring maturities.", r"w(k)=a+b\{\rho(k-m)+\sqrt{(k-m)^2+\eta^2}\}", ("Choose log-forward moneyness and a total-variance representation.", "Fit parameters under explicit admissibility and weighting rules.", "Reprice the fitted slice and inspect wing, butterfly and cross-expiry conditions separately."), "Does nonnegative SVI total variance alone rule out all static arbitrage?", "No. Price convexity and calendar consistency impose additional conditions. A fit must be checked in the relevant price and maturity representations."),
        L("Specify surface dynamics for risk", "Sticky strike and sticky delta describe different ways a quoted surface moves when the underlying moves. They lead to different effective deltas because implied volatility can change with the strike coordinate sampled by the option. Neither rule is a universal law of market behaviour. A desk should state the scenario convention and test risk under alternative dynamics. Calibration risk, skew exposure and term structure can matter even for a portfolio whose parallel vega is small. The interpretation must connect the chosen dynamics to hedges, rather than treating a surface as a static colourful picture.", r"\frac{dC}{dS}=\left.\frac{\partial C}{\partial S}\right|_{\sigma}+\nu\frac{d\sigma_{imp}}{dS}", ("Separate model delta at fixed volatility from the volatility-coordinate response.", "Choose a sticky-strike, sticky-delta or recalibration scenario explicitly.", "Reprice under alternative dynamics and identify residual skew and basis risks."), "Why can two desks agree on today's premium but disagree on effective delta?", "They can assume different surface dynamics or delta coordinates. A current fit does not uniquely determine how volatility is assumed to move with spot."),
        L("Write the quote-cleaning decision", "A useful smile report retains original premium observations, contract conventions, inversion diagnostics, exclusions and fitted-surface checks. State which data are synthetic, stale, crossed or ill-conditioned. Present the single-option root as a model quoting result, not a forecast of realised volatility or an executable quote. For a surface, include a price-space validation and the dynamics used for risk. When a quote fails a bound or contract check, reject or escalate it rather than forcing a volatility. The data-cleaning decision should be reproducible independently of the person who prepared the chart.", r"\mathrm{accept}=\mathrm{contract}\land\mathrm{bounds}\land\mathrm{residual}\land\mathrm{quality}", ("Preserve raw quotes and their timestamps before normalising.", "Attach root, repricing and surface-quality diagnostics.", "Accept with explicit limits or reject/escalate a specific inconsistency."), "What should accompany the statement that a quote implies twenty percent volatility?", "The underlying/strike/expiry/carry conventions, premium target and timestamp, solved repricing residual, and any low-vega or liquidity limitation."),
    ),
    (
        ("Why is a low-vega implied-volatility solve ill-conditioned?", "Small premium errors can produce large changes in the inferred volatility.", ("The option must have no intrinsic value.", "A zero-vega Newton denominator improves convergence.", "The solved volatility becomes a guaranteed realised forecast.", "Bid-offer uncertainty disappears in volatility space."), "The inverse sensitivity is approximately one over vega. Keep the premium residual and quote uncertainty visible in low-vega regions."),
        ("What must happen to a premium outside the declared European-call bounds?", "Reject it under that contract/model and investigate data or conventions.", ("Clamp it silently to a bound.", "Choose an arbitrarily large volatility and call it valid.", "Replace the strike until the root exists.", "Declare a successful fit because the iteration stopped."), "Root existence is a contract and bounds question before it is a numerical one. A solver cannot legitimise an inadmissible target."),
        ("What does a smooth fitted smile fail to guarantee?", "Convex European call prices and absence of butterfly arbitrage.", ("A visually continuous volatility display.", "The existence of a chosen interpolation rule.", "The ability to compute a model price at a supported point.", "A parameterised representation of the observed slice."), "Static arbitrage is a condition on prices and maturity relationships. Smooth volatility alone is insufficient."),
        ("Why can sticky-strike and sticky-delta risk differ at the same current option price?", "They imply different surface responses when spot moves.", ("They must use different contractual strikes today.", "One is always the true physical law.", "They remove every skew exposure after calibration.", "Current premium equality forces identical effective deltas."), "A current surface fit does not uniquely specify dynamics. Risk requires a stated movement convention and checks of the remaining exposures."),
        ("Which quantity is solved by the single-option implied-volatility example?", "A Black–Scholes quoting input reproducing the stated premium under fixed conventions.", ("The future realised volatility with certainty.", "An arbitrage-free complete surface across every expiry.", "The physical probability that the buyer makes money.", "An executable dealer bid including all costs."), "Inversion is conditional on the chosen model, contract and carry. It is neither a market forecast nor a complete commercial quote."),
    ),
)

MONTE = Course(
    "monte-carlo-pricing", "monte_carlo", "Monte Carlo pricing: estimator, uncertainty and controls", "risk-neutral European-call benchmark and path-dependent extension",
    "monte_carlo_gbm", "Monte Carlo European call spot 100 strike 100 volatility 20% maturity 1 risk-free rate 5% dividend yield 0%, 20000 simulations.",
    "Conditional expectations, variance, normal distributions, option payoffs and risk-neutral valuation.",
    "Sampling uncertainty, incorrect payoff/path specification, discretisation and model error. A reproducible seed is not evidence of bias, and a narrow confidence interval does not validate a model.",
    "The worked pack uses risk-neutral GBM, a European call and independent antithetic pair means for sampling error. It does not value every path-dependent contract or forecast physical losses. Monitoring and exercise features require the appropriate payoff and simulation scheme.",
    "mc",
    (
        L("Choose a measure for the question", "Pricing and risk forecasting ask different questions. Under a pricing measure, tradable-asset drift is set by the numeraire and carry assumptions; a physical expected return does not enter as a discretionary bullish forecast. A physical Monte Carlo model can be useful for a loss distribution, but it needs separately justified return dynamics and horizon. A simulator's presence does not identify the measure. State the payoff, numeraire, discounting rule and purpose before generating paths. Otherwise a convincing distribution can answer the wrong economic question with great numerical precision.", r"V_0=E^{Q}[e^{-rT}\Phi]\quad\text{versus}\quad L\sim P", ("Identify whether the task is clean valuation or a physical risk distribution.", "Choose the corresponding measure and drift conventions.", "Apply discounting and payoff definitions consistent with that question."), "Can historical stock-return drift replace risk-neutral carry in the European-call pricing benchmark?", "No. That changes the measure and generally breaks the clean no-arbitrage benchmark. A physical risk experiment must be labelled and validated separately."),
        L("Simulate a lognormal diffusion correctly", "GBM has an exact transition over a time interval for constant coefficients. The negative half-variance drift term in the logarithm ensures the stock expectation grows at carry. Leaving it out biases the simulated asset distribution even if the random normals look sensible. A terminal-only transition is sufficient for a European terminal payoff; an Asian average or barrier needs additional path information or a valid conditional method. Exact GBM transitions remove one kind of time-stepping error, not every source of contract or model error.", r"S_{t+h}=S_t\exp[(r-q-\tfrac12\sigma^2)h+\sigma\sqrt h Z]", ("Apply Itô's lemma to log spot to obtain carry minus half variance.", "Integrate the log diffusion over the interval using a normal increment.", "Exponentiate and verify the expected terminal stock under the pricing measure."), "Why does omitting minus one-half sigma squared in the log step create an error?", "The exponential of a normal variable contains a variance correction. Without it, the expected stock grows faster than the specified carry."),
        L("Construct the discounted estimator", "A Monte Carlo price averages discounted contractual payoffs. Discount the correct cash-flow dates; averaging an undiscounted payoff is not a present value. For multiple coupons or early redemption, process cash flows chronologically and stop when the contract terminates. The plain sample mean is unbiased for the specified integrable payoff when draws and dynamics are correct, but an incorrect payoff definition remains incorrect no matter how many paths are used. Keep the unit basis consistent with the analytic benchmark before applying notional scaling.", r"\widehat V=\frac1M\sum_{m=1}^{M}e^{-rT}\Phi(S_T^{(m)})", ("Evaluate the contract payoff on each valid simulated state or path.", "Discount each cash flow at its proper date under the model.", "Average independent observations on a consistent unit-price basis."), "What does increasing paths fix if the payoff accidentally omits an early-redemption event?", "It reduces sampling noise around the wrong contract value. The payoff implementation must be corrected before more paths provide useful evidence."),
        L("Compute a standard error from independent observations", "The standard error describes the variability of the estimator under repeated sampling. With antithetic draws, the two payoffs in a pair are dependent; use independent pair averages as the observations for variance estimation. Counting both paths as independent gives an unjustified error estimate. A normal-approximation confidence interval requires adequate sample behaviour and finite variance. A single interval can miss a correct benchmark without proving bias. Record the estimator construction, number of independent observations and random seed so another person can reproduce the experiment.", r"SE(\widehat V)=\frac{s_Y}{\sqrt n},\qquad CI_{95}\simeq\widehat V\pm1.96SE", ("Define Y as an independent discounted payoff or independent antithetic pair mean.", "Estimate sample variance across those independent observations.", "Divide its standard deviation by square root of their count and state the interval approximation."), "Why are twenty thousand antithetic paths not twenty thousand independent observations?", "Each positive/negative normal pair is deliberately dependent. There are ten thousand independent pair means when those are the estimator's building blocks."),
        L("Separate sampling and discretisation", "More independent samples reduce standard error roughly at an inverse-square-root rate. Finer time steps address discretisation or monitoring approximation and do not automatically reduce sampling error. Some payoffs admit exact terminal simulation or conditional Brownian-bridge methods; others need a convergence study in time resolution. Keep path count and time-grid refinement as separate experiments. A stable estimate on one coarse monitoring grid can be precisely wrong for a continuously monitored barrier. The confidence interval describes sampling conditional on the implemented scheme, not the distance to every intended contract specification.", r"\mathrm{error}=\mathrm{sampling}+\mathrm{discretisation}+\mathrm{specification/model}", ("Hold the time scheme fixed and vary independent sample count.", "Hold sampling controls fixed and refine the discretisation where relevant.", "Compare both studies with a suitable benchmark or contract-boundary control."), "Does a narrow interval on a coarse barrier grid certify a continuous-barrier price?", "No. Unobserved crossings can create monitoring bias outside that sampling interval. Use a justified bridge correction or a time-grid convergence study."),
        L("Use variance reduction without false certainty", "Antithetic variates exploit dependence to reduce estimator variance; their benefit depends on the payoff. A control variate uses a correlated quantity with a known expectation and must retain the correct centring. Reusing a common random sequence across bumped valuations can reduce the noise of a difference, but the paired structure must be respected in its error estimate. A fixed seed ensures repeatability, not bias. Report the effective variance reduction and computational cost on comparable experiments rather than assuming any named technique guarantees a better estimate.", r"Y_{cv}=Y-\beta(X-E[X])", ("Choose a control with genuinely known expectation under the same model.", "Estimate or specify the coefficient without silently changing the target expectation.", "Measure variance and standard error on the resulting independent estimator observations."), "Why must a control variate's expected value match the simulated model?", "Incorrect centring shifts the estimator's expectation and introduces bias. Correlation alone does not make an arbitrary reference value a valid control."),
        L("Validate with a vanilla benchmark", "A closed-form European call provides a controlled benchmark for the same GBM inputs, carry, payoff and discounting. Compare Monte Carlo error with its reported standard error across seeds or sample counts. Do not demand every 95% interval contain the analytic value; repeated valid intervals have coverage, not certainty. A mismatch in dividend yield, exercise or maturity can dominate sampling noise. Use boundary cases such as negligible volatility or zero quantity where supported. Retain failed experiments and investigate the source of discrepancy rather than selecting only the seed that looks best.", r"z_{MC}=\frac{\widehat V-V_{analytic}}{SE(\widehat V)}", ("Align the analytic and simulated contract and inputs exactly.", "Compute the discrepancy relative to sampling error.", "Repeat a controlled convergence or coverage study without cherry-picking seeds."), "Does changing a fixed seed make a correct estimator biased?", "No. A seed chooses a reproducible draw sequence. Bias concerns the estimator's expectation or specification, not whether one draw differs from another."),
        L("Extend the payoff without reusing the wrong benchmark", "An arithmetic Asian call depends on the average at contractual fixing dates; a European call depends only on the terminal level. They require different payoffs and generally different prices even on the same simulated paths. A geometric Asian payoff may provide a tractable control in a suitable model, but it is not the arithmetic payoff itself. Specify fixing dates, whether the initial observation is included and how past fixings are handled. A generic path chart is not evidence that those contractual details were implemented. Validate each extension against an appropriate independent relation.", r"\Phi_{Asian}=\left(\frac1n\sum_{i=1}^nS_{t_i}-K\right)^+", ("List the actual averaging fixings and any already observed values.", "Compute each path's arithmetic average before applying the positive-part payoff.", "Use a matching Asian control or convergence study, not an equality to a European premium."), "Can a European analytic price be used as the exact answer for the arithmetic Asian extension?", "No. It remains a simulator control for the terminal-payoff case only. The path-dependent contract needs its own payoff and benchmark."),
        L("Estimate simulation Greeks carefully", "A finite-difference Greek divides the difference of two noisy price estimates by a bump. Independent random draws can make that difference unnecessarily noisy. Common random numbers pair the two states and improve comparison, but discontinuous payoffs or small bumps can still cause unstable estimates. Choose bump size through a sensitivity study balancing truncation and sampling error. A pathwise derivative or likelihood-ratio method has its own regularity assumptions. State the method and uncertainty rather than treating every extra digit in a simulated delta as reliable hedge precision.", r"\widehat\Delta_h=\frac{\widehat V(S+h)-\widehat V(S-h)}{2h}", ("Choose a meaningful bump and use paired random inputs where justified.", "Estimate the derivative from differences with correct dependence-aware error.", "Vary the bump and compare against an analytic Greek in the vanilla test."), "Why can making the bump arbitrarily small worsen a simulated Greek?", "The noisy numerator is divided by a smaller number while floating-point effects can grow. Balance sampling and truncation error rather than assuming smaller is always better."),
        L("Report uncertainty and a bounded decision", "A simulation report includes price estimate, standard error, confidence interval, independent observation count, seed, scheme and model boundary. The desk decision compares numerical uncertainty with the relevant quote precision or risk tolerance. Reducing sampling error is worthwhile only after payoff and model controls pass. Explain how the method would need to change for an unsupported feature rather than claiming a universal Monte Carlo pricer. A reproducible teaching run is evidence of a calculation, not a live market quote or future P&L prediction.", r"\mathrm{report}=(\widehat V,SE,CI,n,\mathrm{scheme},\mathrm{limits})", ("Attach uncertainty to the estimator under its actual observation structure.", "Check specification and benchmark before increasing computation.", "Accept the bounded reference, request more precision or escalate the model gap."), "What is the first priority when a price interval is narrow but the contractual payoff is wrong?", "Repair and validate the payoff. More paths only make the wrong-model estimate look more precise."),
    ),
    (
        ("Which drift belongs in the GBM European-call pricing benchmark?", "Risk-neutral carry under the specified numeraire and dividend convention.", ("The buyer's bullish expected historical return.", "Whatever drift maximises the estimated premium.", "The sample average return from yesterday's prices regardless of measure.", "Zero drift because all Monte Carlo models are risk-neutral automatically."), "Measure choice comes from the economic question and model. A simulator does not select it merely by generating random paths."),
        ("What should supply independent observations for an antithetic standard error?", "Independent means of each antithetic payoff pair.", ("Both dependent paths counted as independent.", "The random seed treated as the sample variance.", "Only the largest simulated payoff.", "The analytic price duplicated once for every path."), "Dependence is intentional within each pair. Estimate uncertainty across independent pair means, not a falsely doubled sample size."),
        ("What does quadrupling independent sample count approximately do to standard error?", "It halves standard error when the estimator and variance conditions are unchanged.", ("It eliminates economic model error.", "It quarters standard error by a universal linear law.", "It guarantees every interval covers the analytic price.", "It repairs an incorrect monitoring schedule."), "Monte Carlo sampling error scales like inverse square root of independent observation count. It does not measure specification or model error."),
        ("What follows when a correct analytic value lies outside one nominal 95% Monte Carlo interval?", "Investigate conventions and repeated coverage; one miss alone does not prove bias.", ("The estimator is certainly biased.", "The fixed seed must be illegal.", "The confidence level was necessarily one hundred percent.", "The analytic formula should be replaced by the simulated midpoint."), "A valid 95% procedure can miss in individual runs. Separate sampling variation from systematic specification or implementation errors."),
        ("Why can a fixed-seed coarse-grid barrier simulation remain wrong with many paths?", "Monitoring discretisation can miss crossings outside the reported sampling uncertainty.", ("Repeatability itself biases the estimator.", "Every barrier depends only on the terminal level.", "A large path count proves the contract is correctly specified.", "Confidence intervals include all possible model errors."), "Sampling precision is conditional on the implemented scheme. Correct continuous monitoring needs an appropriate method or a validated refinement study."),
    ),
)

STOCHASTIC = Course(
    "stochastic-calculus-for-hedging", "stochastic", "Stochastic calculus for a replicating hedge", "European option under a diffusion model",
    "vanilla_option_black_scholes", VANILLA.ticket,
    "Ordinary differentiation, Taylor expansion, conditional expectation, Brownian increments and a basic European option contract.",
    "A continuous diffusion hedge leaves real discretisation, jumps, model, funding and liquidity risks. A measure change simplifies valuation without removing economic uncertainty.",
    "One-factor continuous GBM, constant coefficients and a European terminal payoff; frictionless self-financing replication. The numerical checkpoint is the vanilla BS benchmark, not a Monte Carlo SDE solver or a model for all exotic products.",
    "bs-pricer",
    (
        L("Distinguish a path from its increments", "Brownian motion is continuous but not differentiable in the ordinary pathwise sense. Its increments over disjoint intervals are independent normals with variance equal to elapsed time. The size of an increment scales with square root of time, not time. That scaling is why a second-order Taylor contribution survives when a diffusion is transformed. A plot of one simulated path is not evidence about the probability law or independence. State the filtration and what information is available before an adapted hedge is chosen; using future information in a strategy invalidates the economic replication argument.", r"\Delta W\sim N(0,\Delta t),\qquad\Delta W=\sqrt{\Delta t}\,Z", ("Specify an adapted information set and independent future Brownian increments.", "Scale a standard normal by square root of elapsed time.", "Distinguish realised paths from distributional statements about repeated increments."), "Why is replacing a Brownian increment by dt times a standard normal wrong?", "It gives variance of order dt squared rather than dt, suppressing the diffusion's variation and changing the limiting process."),
        L("Understand quadratic variation", "In a diffusion limit, the sum of squared Brownian increments converges to elapsed time. Individual increments have mean zero, yet their squared contributions do not disappear. Products of dt with a diffusion increment and dt squared vanish at the relevant order. This is the bookkeeping behind Itô's correction, not ordinary algebra in which every infinitesimal squared is set to zero. Quadratic variation describes accumulated path variability and is distinct from the square of the total return. Jumps add another contribution and require an extended calculus.", r"[W]_T=T,\qquad(dW)^2=dt", ("Partition time and sum squared independent Brownian increments.", "Track their non-vanishing accumulated variation as the mesh shrinks.", "Retain second-order diffusion terms while dropping higher-order dt products."), "How can a process with zero-mean increments generate a nonzero Itô correction?", "The correction depends on squared increments, whose accumulated quadratic variation is positive. Mean-zero first-order changes do not imply zero second-order variation."),
        L("Apply Itô's lemma", "For a smooth function of time and a diffusion, Itô's lemma adds a second-derivative term to the ordinary chain rule. The function must have the required regularity, and the diffusion coefficient determines the quadratic-variation contribution. For an option value, the time derivative, delta and gamma have economic interpretations. At a nonsmooth payoff boundary, a pricing argument normally works before maturity with the appropriate terminal condition rather than casually differentiating the kink as an ordinary smooth function. Keep the source of each derivative visible.", r"dV=(V_t+\mu S V_S+\tfrac12\sigma^2S^2V_{SS})dt+\sigma S V_SdW", ("Expand value to first order in time and second order in spot.", "Substitute dS and retain its squared diffusion contribution.", "Collect the drift and diffusion coefficients, naming the smoothness assumptions."), "Which term would an ordinary first-order chain rule miss in diffusion option valuation?", "The half-variance-times-gamma term. It survives because squared diffusion increments accumulate at order dt."),
        L("Derive the lognormal transition", "Applying Itô's lemma to log spot removes the multiplicative spot factor from the diffusion coefficient. The second derivative of the logarithm generates a negative half-variance adjustment to drift. Integrating then gives the exact GBM transition under constant coefficients. The resulting stock expectation and log-return expectation differ; confusing them causes an incorrect simulated growth rate. This construction assumes strictly positive spot and continuous diffusion paths. A model with jumps or nonconstant coefficients can require a different transition and cannot be made exact by reusing the same formula without justification.", r"d\log S=(\mu-\tfrac12\sigma^2)dt+\sigma dW", ("Differentiate log spot once and twice.", "Insert those derivatives into Itô's lemma and simplify.", "Integrate the constant-coefficient log process and exponentiate to recover spot."), "Why does log-return drift differ from proportional expected stock growth?", "The logarithm is nonlinear. Its Itô correction and the exponential-normal expectation produce the half-variance difference."),
        L("Construct a self-financing delta hedge", "A replicating portfolio's changing stock holding must be financed through the cash account; rebalancing is not free external cash. With continuous dividends, total gains include the stock's dividend income. Taking the option delta in stock exposure cancels its instantaneous Brownian risk under the diffusion model. The remaining self-financing cash flow must earn the funding rate to prevent arbitrage. A real hedge is discrete and subject to market frictions, so theoretical cancellation does not certify a realised zero-loss strategy. Keep the financing and position sign explicit.", r"\Delta=V_S,\qquad d\Pi\ \text{has no diffusion term under the ideal hedge}", ("Write the option's Itô expansion and the stock/cash gains process.", "Set the stock holding to the option derivative and fund rebalancing self-financingly.", "Cancel the Brownian term and impose risk-free growth on the remaining idealised position."), "Why is self-financing more than the statement that delta equals the price derivative?", "It specifies how stock rebalancing and cash-account changes are funded. Without the gains and financing condition, diffusion cancellation alone is not a complete replication strategy."),
        L("Obtain the pricing PDE", "Eliminating the Brownian component from the self-financing hedge removes the stock's physical expected return from the no-arbitrage relation. The resulting PDE contains carry, variance, time decay and funding. It needs a terminal payoff and suitable boundary conditions to identify the solution. A PDE without a contract is not a price. The cancellation also does not assert that every risk in a real market is hedgeable. Jumps, stochastic volatility, transaction costs or funding differences can invalidate the assumptions behind this complete one-factor representation.", r"V_t+(r-q)SV_S+\tfrac12\sigma^2S^2V_{SS}-rV=0", ("Equate the locally riskless self-financing portfolio's drift to risk-free growth.", "Collect terms and observe cancellation of the physical stock drift.", "Attach the European payoff at maturity and the contract's relevant boundaries."), "Can one solve the pricing PDE without saying whether the payoff is a call, put or barrier?", "Not uniquely. The terminal and boundary conditions encode the contract, and different conditions produce different economic values."),
        L("Interpret a change of measure", "An equivalent pricing measure changes drift so discounted tradable gains are martingales under the chosen numeraire, subject to the model's technical conditions. It does not change historical observations or imply that all investors become risk neutral. The money-market numeraire leads to the familiar risk-neutral carry convention; another numeraire can simplify a different payoff. Measure existence and uniqueness depend on absence of arbitrage and market completeness assumptions. An interview answer should connect the formal transformation to what is being priced, rather than recite a measure name without its asset and discounting convention.", r"dS=(r-q)Sdt+\sigma SdW^Q", ("Specify the numeraire and discounted gains that should be martingales.", "Adjust drift under an equivalent measure while preserving the diffusion structure.", "Price the matching payoff using the associated expectation and discount factor."), "Does risk-neutral valuation say real investors do not care about risk?", "No. It is a no-arbitrage valuation representation associated with a numeraire and hedgeable dynamics, not a claim about investor preferences."),
        L("Connect PDE and expectation", "The Feynman–Kac representation links a suitable PDE solution with a discounted conditional expectation under the pricing dynamics. It provides two representations of the same model value when regularity and integrability conditions hold. It does not make every numerical PDE or Monte Carlo scheme equally accurate. A European GBM option offers a closed-form benchmark for both. A changed payoff must appear in the terminal condition or path state, and a changed discounting convention must appear in the representation. Comparing representations is a useful implementation control only after those economic inputs match.", r"V(t,S)=E^Q[e^{-r(T-t)}\Phi(S_T)\mid S_t=S]", ("Specify the diffusion generator and discounting term in the PDE.", "Match its terminal condition to the contractual payoff.", "Use the conditional expectation representation under the same dynamics and admissibility assumptions."), "What is controlled by comparing a PDE solution with Monte Carlo on the same payoff?", "Numerical implementations of one model can be compared. Agreement does not validate that model against jumps, liquidity or an incorrectly specified contract."),
        L("Explain discrete hedging error", "Continuous rebalancing is an idealisation. Over a finite hedge interval, gamma exposure interacts with the realised squared underlying move, and transaction costs make arbitrarily frequent rebalancing expensive. Model volatility and realised path variation need not coincide. A delta-neutral opening position can therefore produce nonzero P&L, and jumps can create losses outside a continuous-diffusion explanation. Preserve the actual hedge dates, fills and financing before attributing a residual to the model. The mathematical limit helps identify the missing mechanism rather than guaranteeing a zero-error practical strategy.", r"\Delta V\simeq\Delta\Delta S+\tfrac12\Gamma(\Delta S)^2+\Theta\Delta t", ("Apply a finite-interval Taylor expansion around the previous hedge state.", "Subtract the P&L of the actual discrete underlying hedge.", "Attribute the residual to curvature, variance mismatch, costs, jumps and omitted terms as appropriate."), "Why does an initially delta-neutral option hedge still have P&L?", "Delta changes, the path has realised variation, and the hedge is discrete and costly. Other factors such as volatility and jumps can remain exposed."),
        L("Defend the mathematical boundary", "A strong final explanation moves from Brownian scaling to Itô, self-financing replication, PDE and conditional expectation, then returns to the actual contract and hedge limitations. Each implication has assumptions. Do not infer that a complete diffusion market describes every desk risk, or that a successful analytic price proves a real hedge is risk-free. Explain what changes under a jump, stochastic volatility or an untradeable factor and why a different market-completeness argument may be needed. The numerical vanilla checkpoint demonstrates the current model, not an unlimited pricing capability.", r"\mathrm{diffusion}\to\mathrm{It\hat{o}}\to\mathrm{replication}\to\mathrm{PDE}\leftrightarrow E^Q", ("State the assumptions used at each mathematical step.", "Reproduce the vanilla benchmark and an independent parity or derivative control.", "Identify a changed assumption that breaks replication or requires a richer state/model."), "What is the defensible answer when asked whether delta hedging removes all market risk?", "It removes instantaneous diffusion risk in the stated ideal model. Real discrete hedging, jumps, model uncertainty, funding and liquidity require separate treatment."),
    ),
    (
        ("What creates the second-derivative term in Itô's lemma?", "The non-vanishing quadratic variation of diffusion increments.", ("A nonzero mean Brownian increment.", "Ordinary dt-squared terms dominating all other terms.", "An assumption that the option payoff has no kink.", "Investors becoming indifferent to risk."), "Brownian increments are order square-root time, so their squared contributions accumulate at order time. Mean-zero increments do not eliminate that correction."),
        ("What accompanies delta selection in a replication argument?", "A self-financing stock/cash gains process, including funding and relevant dividends.", ("Unlimited external cash injections without accounting.", "A promise of zero loss in every real discrete hedge.", "Dropping all terminal payoff conditions.", "Using future stock information to choose today's hedge."), "Diffusion cancellation is only part of replication. The financing constraint, adapted strategy and contractual boundary are essential."),
        ("Why does the physical stock drift disappear from the ideal European pricing PDE?", "It cancels when the self-financing delta hedge removes the diffusion exposure.", ("Actual investors universally have zero risk aversion.", "Historical returns are identically zero.", "The derivative payoff is independent of stock.", "Funding and dividend assumptions are unnecessary."), "The no-arbitrage replication removes the physical drift under the specified complete diffusion model. It does not remove real-world risk preferences."),
        ("Which claim about a PDE and expectation representation is correct?", "They describe the same contract/model under matching dynamics, boundaries and technical conditions.", ("They certify the model against every market risk.", "They can use different payoffs and still be an exact control.", "They guarantee numerical schemes have no discretisation error.", "They remove the need for a discounting convention."), "The equivalence is conditional. Numerical implementation and empirical model validity remain separate questions."),
        ("What does a continuous-diffusion delta hedge fail to guarantee in practice?", "Zero realised loss under discrete trading, jumps, costs and model uncertainty.", ("Cancellation of the ideal model's local Brownian term.", "The need for a signed hedge position.", "The existence of an option-price derivative under the stated smoothness conditions.", "A conditional pricing representation for the vanilla model."), "The theoretical hedge result has explicit assumptions. Real trading introduces mechanisms outside that idealised cancellation."),
    ),
)

BARRIER = Course(
    "barrier-options-gap-risk", "barrier", "Barrier options: monitoring, payoff and gap risk", "FX down-and-out call",
    "fx_barrier_option", "FX down-and-out call spot 1.0800 strike 1.1000 barrier 1.0000 notional EUR 10m. Terminal spot 1.0500, terminal spot 1.2000.",
    "Vanilla option payoffs, FX quote direction, path extrema, conditional events and continuous versus discrete observation.",
    "Knock-out discontinuity, monitoring mismatch, delta jumps, gap risk and FX settlement/numeraire conventions. A terminal spot does not tell whether the barrier was hit earlier.",
    "The main FX pack computes conditional terminal payoffs assuming the down barrier has not been hit; it is not a current premium. Monitoring history, equality-at-touch, rebate, expiry, rates and volatility must be supplied for valuation. The separate original notebook prices a non-dividend GBM continuously monitored zero-rebate down-and-out call with H <= K; it is not a general FX exotic engine.",
    None,
    (
        L("Specify the event, not only the strike", "A down-and-out call stops existing when its contractual barrier event occurs. The final underlying level alone is insufficient: a path can fall through the barrier and later finish above strike, yet the option remains knocked out. Specify whether touching equality counts, the monitoring window and frequency, the source of observations and any rebate. For FX, state quote direction, premium currency and the currency amount to which the payoff applies. A barrier label without those fields does not define one reproducible payoff or price.", r"\Phi=(S_T-K)^+\mathbf1_{\min_{0\le t\le T}S_t>H}", ("Define the down-barrier event including equality and monitoring times.", "Evaluate whether the contract survives along the observed path.", "Apply the vanilla terminal payoff only if the contract remains alive."), "A path touches the knock-out level then rallies above strike. Is a positive payoff guaranteed?", "No. Under the stated touch-knocks-out rule and zero rebate, the option has terminated. A later rally does not resurrect it."),
        L("Separate conditional payoff from premium", "Multiplying a positive terminal FX rate difference by foreign notional gives a conditional domestic-currency cash payoff. It does not integrate over path outcomes or discount to today. A premium needs a probability model under an appropriate numeraire and the contractual monitoring specification. Survival can be highly correlated with the terminal payoff, so multiplying a vanilla premium by an arbitrary unconditional survival rate is generally invalid. The course's first calculation deliberately answers a bounded payoff question; identify its conditioning before interpreting a large cash number as an attractive investment.", r"\mathrm{payoff}_{dom}=N_{for}(S_T-K)^+\mathbf1_{alive}", ("Express spot and strike as domestic currency per foreign unit.", "Multiply the positive rate difference by foreign notional.", "Apply barrier survival and distinguish the resulting expiry cash amount from present value."), "Can the one-million payoff scenario be reported as today's option price?", "No. It is an expiry cash amount conditional on the stated path history. Today's price requires valuation across possible paths and discounting."),
        L("Use in-out parity under matching terms", "For a matching zero-rebate knock-in and knock-out pair, the mutually exclusive barrier states partition the vanilla payoff. Their prices therefore sum to the vanilla price under consistent monitoring, exercise, expiry and other terms. Rebates or mismatched observation rules can change the relation. This is a useful independent control for a barrier engine, but it does not determine either component alone. A low knock-out price can reflect a high probability or high-value contribution of knock-in states, not an arbitrage discount on the same vanilla claim.", r"V_{in}+V_{out}=V_{vanilla}\quad\text{(matching zero-rebate terms)}", ("Partition each path into barrier-hit and barrier-not-hit states.", "Add the two matching conditional payoffs path by path.", "Apply linear valuation under the same model and discounting."), "Why is comparing a cheap knock-out directly with a vanilla call misleading?", "The knock-out has fewer payoff states and different hedge risk. Matching in-out parity clarifies the missing exposure rather than treating the premium difference as free value."),
        L("Respect continuous versus discrete monitoring", "A discrete observation grid can miss barrier crossings between dates. Using the same path endpoints does not make a discretely monitored option identical to a continuously monitored one. Brownian-bridge survival methods can integrate intervening crossings under a compatible diffusion; monitoring adjustments are approximations with explicit conditions. Real jumps, fixing conventions and trading interruptions can invalidate simple corrections. Keep the contractual monitoring regime in the model input and benchmark. Increasing the number of simulated paths without changing a wrong monitoring specification reduces noise around the wrong price.", r"P(\mathrm{survive}\mid S_0,S_T)=1-\exp\!\left[-\frac{2\log(S_0/H)\log(S_T/H)}{\sigma^2T}\right]", ("Condition on positive endpoints above the down barrier under lognormal diffusion.", "Use the Brownian-bridge crossing probability for the intervening path.", "Weight the terminal payoff by survival only under the compatible continuous-monitoring model."), "What does a coarse endpoint-only simulation miss for a continuous down barrier?", "It can miss intermediate crossings and overstate survival. A bridge method or justified time-grid convergence is needed; extra paths alone do not fix it."),
        L("Explain the hedge discontinuity", "As spot approaches a knock-out barrier, the value and hedge can change rapidly, depending on strike, barrier and remaining time. The risk is not captured by asserting that every option has an ordinary smooth vanilla delta everywhere. On knock-out, an existing hedge may need to be unwound immediately. Market liquidity and price gaps can prevent execution at the assumed barrier level. State the position side and pre-hit hedge before calculating a possible unwind loss. A conditional payoff table cannot estimate that loss without hedge and execution assumptions.", r"\mathrm{hedge\ gap\ P\&L}=h_{pre}\,(S_{exit}-S_{reference})", ("Identify the actual signed underlying hedge before the event.", "Specify the reference execution level and the achievable exit price.", "Compute the hedge cash change and keep option termination/rebate accounting separate."), "Why does a correct model delta fail to guarantee a loss-free barrier unwind?", "The market can gap or become illiquid when the event occurs. The hedge cannot necessarily be traded at the model's continuous path or barrier execution assumption."),
        L("Stress path history and gap scenarios", "Two paths with the same terminal spot can produce different barrier outcomes. A useful stress set therefore changes both path history and terminal level, and includes a gap through the barrier. Separate contractual termination from the economic result of carrying and unwinding a hedge. If the barrier is monitored only at specified fixings, an intraday excursion may have a different contractual consequence from a continuous rule. Do not assign probabilities to synthetic path scenarios unless a separately validated distribution supports them. Preserve the chosen observation source and event convention in the final case record.", r"S_T^{(a)}=S_T^{(b)}\not\Rightarrow\Phi^{(a)}=\Phi^{(b)}", ("Construct equal-terminal-level paths with different minima.", "Evaluate the contractual monitoring event on each path.", "Assess hedge execution separately under the selected gap scenario."), "What is the minimum extra information needed beyond terminal spot to evaluate the main payoff table?", "Whether the specified monitoring rule recorded a knock-out event. For a continuous down barrier, the relevant path minimum or equivalent event history is essential."),
        L("Benchmark a bounded analytic and bridge model", "The original down-and-out notebook provides a separate controlled laboratory: positive GBM, flat rates and volatility, zero dividends and rebate, continuous monitoring and barrier no higher than strike. It compares a closed form with conditional bridge Monte Carlo using independent antithetic pair means. This benchmark is useful precisely because its domain is narrow and explicit. It must not be relabelled as a general multi-currency or multi-asset pricer. A successful estimate within sampling tolerance checks that bounded implementation; model validity and the exact market contract remain separate questions.", r"\widehat V_{out}=e^{-rT}\,\overline{(S_T-K)^+P(alive\mid S_0,S_T)}", ("Check that the notebook ticket lies inside the analytic model's supported domain.", "Compare its closed form and bridge estimator with dependence-aware uncertainty.", "Explain which FX rates, dividends, rebate or monitoring changes require another model."), "Can a no-dividend single-asset bridge notebook price an arbitrary FX barrier without adaptation?", "No. FX numeraire/carry, contractual monitoring and other features must be handled explicitly. Keep the notebook as an independent bounded model experiment."),
        L("Choose operational controls near the barrier", "Operational controls should identify the live contract state, observation source, trigger notification and hedge-unwind responsibility before an event. A chart threshold without a documented fixing rule can produce a dispute over whether the option survived. Test both equality and just-above/just-below states in code. Preserve event times and the actual market observations rather than inferring history from today's price. A desk decision may reduce exposure or escalate a monitoring uncertainty even if a model price is available. The control target is the contract and the feasible hedge, not visual smoothness of a pricing curve.", r"\mathrm{state}\in\{alive,knocked\ out,redeemed\ rebate\}", ("Record the contractual observation source and event time.", "Apply a deterministic state transition with explicit equality and rebate rules.", "Reconcile hedge ownership, execution and cash settlement after termination."), "What should happen when two observation sources disagree on a barrier touch?", "Escalate according to the contract's designated fixing and dispute process. Do not choose whichever screen preserves the desired payoff."),
        L("Defend the exotic quote boundary", "The final memo must distinguish conditional payoff, model premium and hedge-gap stress. State FX quote direction, notional basis, monitoring history and any rebate. Present the numerical scenario with its condition, then explain what additional data and model are required for a price. Name the dominant event risk and an operational control. If asked for an unsupported exotic extension, decline that calculation explicitly while preserving the valid bounded result. A credible candidate can explain why a number cannot yet be responsibly promoted to a tradeable quote.", r"\mathrm{deliverable}\ne\mathrm{payoff}\ne\mathrm{price}\ne\mathrm{hedge\ loss}", ("Label each number by its economic object and currency.", "Check event history and the exact model domain.", "Quote conditionally, reduce event exposure or escalate the unsupported feature."), "What is missing from a two-row terminal payoff table for a full FX barrier quote?", "The complete monitoring/rebate contract, valuation date and expiry, domestic/foreign carry, volatility dynamics and path valuation. The table alone is not a fair-value engine."),
    ),
    (
        ("What can distinguish two down-and-out paths with the same final spot?", "One path may have triggered the knock-out before expiry.", ("Their terminal vanilla intrinsic values must differ.", "The strike must be changed after a touch.", "The option always resurrects after a rally.", "Monitoring history never affects a barrier payoff."), "Barrier claims depend on their event history. Terminal spot alone is not enough to reconstruct survival."),
        ("What does the main FX barrier calculation actually provide?", "Conditional expiry payoffs assuming the barrier survival condition holds.", ("Today's complete model premium.", "A probability of a profitable investment.", "The actual hedge-unwind loss at every possible touch.", "A general multi-asset barrier engine."), "Its number is a bounded cash-flow calculation. Pricing and hedge-gap analysis require additional assumptions and methods."),
        ("When is zero-rebate in-out parity a valid control?", "For matching knock-in, knock-out and vanilla terms with the same monitoring and model basis.", ("For any contracts sharing only the word barrier.", "After ignoring rebates and changing expiry.", "Only when the final spot equals the initial spot.", "As a way to infer a unique barrier price from vanilla alone."), "The partition is pathwise only for matching claims. It validates a relation but does not determine each component independently."),
        ("Why can more endpoint-only simulated paths fail to correct a continuous-barrier price?", "They reduce sampling error while still missing between-date crossings.", ("A fixed seed is necessarily biased.", "Continuous and monthly monitoring define identical contracts.", "Barrier events depend only on volatility's sign.", "Confidence intervals include all discretisation and model error."), "Monitoring bias is a specification/scheme issue. It requires an appropriate crossing treatment or convergence control."),
        ("What creates hedge-gap risk at a knock-out event?", "The pre-event hedge may be unwound only after a discontinuous or illiquid market move.", ("A guarantee of execution exactly at the barrier.", "A contractual right to cancel all hedge losses.", "The fact that every premium is already a realised profit.", "An assumption that delta hedging removes jumps."), "Theoretical continuous replication does not guarantee practical execution at the event level. Track the signed hedge and actual exit assumptions."),
    ),
)

CDS = Course(
    "credit-derivatives-cds", "cds", "CDS: protection, premium, CS01 and default risk", "single-name protection-buyer CDS",
    "cds_cs01", "CDS protection buyer notional 50m spread 120bp risky annuity 4.2 recovery 40%, spread widens 25bp.",
    "Discounted cash flows, survival probabilities, recovery, basis points and a signed protection-buyer position.",
    "A protection buyer gains locally from spread widening but pays running premium. Spread sensitivity does not reproduce jump-to-default, recovery or single-name/index basis risk.",
    "Supplied risky annuity frozen for local spread-risk estimates; recovery assumed 40% and annual premium shown at the stated fair spread. A 100bp standard-coupon upfront illustration is simplified, not a full ISDA model, settlement calculation or survival-curve calibration.",
    None,
    (
        L("Identify buyer and seller cash flows", "A CDS protection buyer pays premium and receives a contractual payment following a qualifying credit event, subject to documentation and settlement rules. The protection seller has the opposite exposure. A long credit-risk position and a long protection position are not interchangeable phrases. State the referenced entity, notional, seniority, maturity and event definition before interpreting spread moves. Default protection does not mean the buyer owns a risk-free asset: counterparty, settlement and basis risks can remain. The teaching ticket uses an explicit protection-buyer perspective throughout.", r"\mathrm{buyer\ PV}=PV_{protection}-PV_{premium}", ("List premium payments while the contract is alive.", "Specify the protection settlement conditional on a qualifying default event.", "Take protection receipts minus premium payments for the buyer sign."), "Does a CDS buyer receive the running coupon as positive carry?", "No. The protection buyer pays the contractual premium. Protection value and gains from spread widening are separate from that premium cash outflow."),
        L("Discount survival-contingent premiums", "Risky annuity weights premium accruals by both discounting and survival to the relevant payment states. It differs from a risk-free swap annuity. Accrual-on-default and exact timing conventions add terms in a production CDS model. Holding risky annuity fixed simplifies local spread sensitivity, but changing hazard or recovery can change it. Do not treat an assumed annuity as a fully calibrated survival curve. Its units allow a decimal premium rate times notional to be converted into PV, with the survival conditioning visible.", r"A_{risky}\simeq\sum_i\alpha_iDF_iQ(\tau>t_i)", ("Define premium dates and accrual fractions.", "Weight surviving scheduled payments by discount factors and survival probabilities.", "Add production-specific accrual/default treatment when the contract requires it."), "Why can a CDS risky annuity differ from a same-maturity risk-free swap annuity?", "Premium payments can cease or settle differently after default, so survival and default-accrual treatment change the weights."),
        L("Relate hazard and spread carefully", "With constant hazard, constant recovery and simplified continuous premium assumptions, fair spread is approximately hazard times loss given default. This is a useful scale intuition, not a universal calibration equation. Real curves, discounting, accrual-on-default and conventions affect the relationship. Recovery is an assumption, not a number inferred uniquely from one spread. Higher observed spreads can reflect changed risk-neutral default compensation and liquidity as well as physical default expectations. A CDS quote alone does not directly identify a real-world probability of default.", r"s\approx\lambda(1-R)\quad\text{under simplified assumptions}", ("Write the protection leg using hazard, survival and loss given default.", "Write the corresponding continuous premium leg.", "Under constant compatible assumptions, divide the two legs to obtain the approximation."), "Can one divide a market spread by loss given default and call it the actual default probability?", "No. The result is a model-dependent hazard approximation in pricing terms, not a directly observed physical default probability over an unspecified horizon."),
        L("Compute running premium and premium PV", "Annual running premium is a cash-flow rate times notional. Premium-leg PV additionally uses the survival-discount annuity. These are different quantities with different time meaning. An existing standard-coupon contract continues to pay its contractual coupon when market spread changes; its premium carry does not automatically rise to the new fair spread. An upfront payment can reconcile market value and a standard coupon. Keep fair-spread illustrations, contractual running coupon and present-value differences separate so a cash-flow calculation is not mistaken for the buyer's net profit.", r"\mathrm{annual\ premium}=Ns,\qquad PV_{premium}\simeq NsA_{risky}", ("Convert basis-point spread to a decimal rate.", "Multiply by notional for the annual premium amount.", "Apply risky annuity for premium-leg PV and use contractual coupon for an existing trade."), "After widening, does an existing fixed-coupon CDS automatically pay a higher running premium?", "No. Its contractual coupon remains fixed. Its market value and possibly quoted upfront change with the market spread and survival assumptions."),
        L("Derive signed spread sensitivity", "The positive CS01 magnitude gives the local PV response scale to a one-basis-point spread change under a frozen-risky-annuity approximation. A protection buyer gains mark-to-market on widening because the protection becomes more expensive relative to the old contractual terms. A seller loses under the same local convention. Some systems sign CS01 differently, so ask for the actual upward-spread bump definition. A spread shock is not a default event and does not justify substituting the jump-to-default cash amount for the sensitivity estimate.", r"|CS01|=NA_{risky}10^{-4},\qquad\Delta PV_{buyer}\simeq|CS01|\Delta s_{bp}", ("Differentiate the local buyer-value expression with respect to fair spread.", "Convert a decimal basis point into currency magnitude.", "Apply widening/tightening and position side consistently."), "Why does positive CS01 magnitude not universally mean a loss on widening?", "A magnitude omits side and sign convention. In this explicit protection-buyer example, widening creates a local mark-to-market gain."),
        L("Distinguish spread movement from default", "Jump-to-default is a discontinuous contractual event, not simply a very large infinitesimal spread move. With the stated recovery assumption, the gross protection settlement scale is notional times loss given default. Net realised P&L also depends on premium accrual, initial market value, upfront, costs and the actual settlement. Recovery changes both loss and pricing assumptions. A CS01 hedge can reduce local spread exposure without matching default-event or recovery risk, especially when an index is used for a single-name position.", r"\mathrm{gross\ protection\ settlement}\simeq N(1-R)", ("Specify the qualifying event and assumed settlement recovery.", "Calculate gross loss-given-default protection cash scale.", "Reconcile existing PV, premium/accrual and settlement before reporting net P&L."), "Is notional times loss given default the buyer's full net profit?", "No. It is a gross protection-payment scale under the assumption. Paid premium, upfront, current PV and settlement details affect net economics."),
        L("Understand standard coupon and upfront", "A standard running coupon allows otherwise comparable trades to exchange an upfront amount when market fair spread differs from that coupon. Under the simplified annuity representation, the buyer pays positive upfront when market spread exceeds the standard coupon. A production upfront calculation uses detailed survival and accrual conventions. Keep upfront as an initial cash exchange and running coupon as continuing contractual payments. An upfront amount is not a second annual premium and should not be added repeatedly across years. Quote sign from the actual payer's perspective.", r"U_{buyer\ pays}\simeq N(s-c_{standard})A_{risky}", ("Value fair-spread and standard-coupon premium legs on the same risky annuity.", "Take their PV difference with the stated buyer payment convention.", "Keep upfront, running coupon and protection-leg settlement as distinct cash flows."), "Why is positive simplified upfront paid by the buyer when market spread is above the standard coupon?", "The buyer receives relatively cheap running protection at the lower standard coupon and compensates the seller through the initial payment."),
        L("Propose a hedge and name its basis", "A CDS hedge should identify whether it targets spread delta, default exposure or recovery. An offsetting same-name contract can still differ in maturity, seniority or documentation. An index hedge may be liquid but leaves single-name/index basis and different event composition. Compare the hedge's actual CS01 with the target exposure and inspect default scenarios separately. The final memo must preserve buyer/seller side, premium cash-flow sign, frozen-annuity assumption and the distinction between gross protection cash and net P&L. Escalate missing contract documentation rather than guessing the settlement rule.", r"h=-\frac{CS01_{target,signed}}{CS01_{hedge,signed}}", ("Choose a hedge contract and compatible signed spread-risk coordinates.", "Solve the local CS01 offset using actual hedge sensitivity.", "Stress default, recovery and basis residuals before recommending the hedge."), "What remains after a single-name CDS position is CS01-hedged with an index?", "The index does not replicate the single entity's default, recovery, documentation or spread basis. State those residual risks and the liquidity trade-off."),
    ),
    (
        ("For the protection-buyer convention in this course, what is the local effect of spread widening?", "A positive mark-to-market contribution under the frozen-risky-annuity approximation.", ("A guaranteed total net loss for every buyer.", "An automatic increase in the existing contractual running coupon.", "An immediate default settlement equal to full notional.", "No change because premium coupons are fixed."), "The protection becomes more valuable relative to contractual terms. Running cash carry, local mark-to-market and actual default are distinct mechanisms."),
        ("What does annual premium differ from premium-leg PV by?", "Premium-leg PV includes discounted survival-contingent accrual weights.", ("Premium PV is always annual premium multiplied by zero.", "Annual premium already includes every future default state.", "Risky annuity is identical to notional principal.", "The difference is only the sign of the colour on a screen."), "Annual premium is a flow rate times notional; PV weights future contractual payments and survival. Their time meaning and dimensions differ."),
        ("What does notional times loss given default represent in the teaching default example?", "A gross protection-settlement scale, not the full net realised trade profit.", ("The exact annual running premium.", "The physical default probability.", "A guarantee that all upfront and accrued premium are zero.", "A complete settlement under every documentation convention."), "Net economics also depend on prior premium, upfront, market value and actual event settlement. Keep gross and net quantities distinct."),
        ("What happens to an existing standard running coupon when fair market spread widens?", "It remains contractual; market value and quoted upfront can change.", ("It automatically resets to the new spread without a contract provision.", "It becomes the recovery rate.", "It cancels every previously paid premium.", "It guarantees positive income to a protection buyer."), "The contract's cash-flow terms do not automatically become today's fair terms. Valuation records the resulting difference."),
        ("What does matching single-name CS01 with a credit index fail to remove?", "Single-name/index basis, default, recovery and documentation mismatches.", ("Only the reported parallel-spread number under the chosen local convention.", "All remaining possible loss by definition.", "The need to identify buyer or seller side.", "The fact that a running premium is a cash flow."), "A liquid proxy hedge can offset one risk coordinate while leaving different event and basis exposures."),
    ),
)

AUTOCALL = Course(
    "structured-products-autocall", "autocall", "Autocallables: turn a term sheet into cash-flow states", "single-index memory-coupon autocallable note",
    "autocall_structured", "Autocall Athena initial level 100, autocall barrier 100%, coupon barrier 70%, protection barrier 60%, coupon 6% per observation with memory, notional 1m. Observed levels: 65, 102.",
    "Conditional cash flows, observation dates, option payoffs, discounting and the difference between cash receipts and net profit.",
    "Early redemption, coupon interruption, contingent capital loss, issuer credit, reinvestment and nonlinear volatility/dividend/correlation exposures. A high conditional coupon does not establish a high expected return or suitability.",
    "Single-index synthetic term sheet; coupon and autocall tests at stated observations, memory enabled, European capital-protection barrier at maturity and no issuer default model. The worked result is a cash-flow scenario, not current fair value or an investment recommendation. A real multi-asset worst-of note requires explicit joint dynamics and exact legal terms.",
    None,
    (
        L("Normalise the term sheet", "An autocallable combines scheduled observations, coupon conditions, early redemption and a final capital rule. Those components are not interchangeable barriers. Convert percentages into levels relative to the initial fixing and retain each observation date. Specify memory, call protection, observation lags, settlement, issuer obligations and the final downside rule. Marketing language such as protected or income does not substitute for cash-flow conditions. The example is a single-index synthetic note, so a worst-of feature must not be silently imported from a familiar product name.", r"B_{level}=b\,S_0", ("Separate initial fixing, coupon, autocall and protection percentages.", "Map each threshold to its observation dates and cash-flow rule.", "Retain equality conditions, memory and settlement in a normalised state machine."), "Does the coupon barrier also define whether principal is protected at maturity?", "Not in this term sheet. Coupon, early-redemption and final capital conditions are distinct. Read each threshold's role and observation rule."),
        L("Process observations chronologically", "The note's state changes at each observation. A coupon can be paid or deferred into memory; an autocall can redeem principal and terminate subsequent events. Event order matters if coupon and call occur on the same date. Specify whether the coupon is paid with redemption under the actual terms. Once the note has terminated, it cannot collect later coupons or re-enter a capital-loss state. A scenario table should therefore include the live/dead state and accumulated memory, not just compare a final underlying level with several thresholds.", r"state_{i+1}=g(state_i,S_{t_i},\mathrm{terms}_i)", ("Start with alive status, principal outstanding and empty coupon memory.", "Apply the current coupon and autocall rules in the stated contractual order.", "Stop future observations after early redemption and record settlement cash flows."), "Can a scenario continue paying scheduled coupons after an autocall?", "No, unless the contract explicitly defines a separate already accrued settlement. The note has terminated; processing later observations double counts cash flows."),
        L("Model coupon memory explicitly", "Memory is a contractual accumulator of missed eligible coupons, not compound interest on an assumed bank balance. A later successful coupon observation may release current and stored amounts under the stated rule. Without memory, the missed coupons may be lost. Coupon rate can be per observation or annualised; frequency conversion is not optional. The example uses six percent per observation and memory. Interpreting the same number as an annual rate changes the economic contract and can materially overstate or understate the cash receipts.", r"M_{i+1}=\begin{cases}0,&\text{coupon paid}\\M_i+c_i,&\text{coupon missed}\end{cases}", ("Store the unpaid coupon entitlement when its observation fails.", "At an eligible payment, add current coupon and contractual memory.", "Reset memory according to the term sheet rather than assuming compounding."), "Why is twelve percent released after the two observations not an annualised guaranteed yield?", "It is the sum of two six-percent observation coupons under this path and memory rule. Actual timing, early redemption and other scenarios determine investment economics."),
        L("Apply the autocall condition", "The autocall event normally repays principal early when the underlying meets a threshold on an eligible observation. It truncates the investor's future exposure and creates reinvestment risk. A product can have a non-call period or a changing call threshold; those terms must be explicit. The issuer does not choose to keep a mechanically autocalling note alive merely because later coupons would be attractive. In the example, the second observation above the initial level triggers redemption and releases the relevant memory coupon under the stated rules.", r"I_{call,i}=\mathbf1_{alive}\mathbf1_{S_{t_i}\ge b_{call,i}S_0}", ("Check that the note is alive and the date is eligible for autocall.", "Compare the observed level with that date's call threshold.", "Pay contractual redemption and terminate future cash-flow processing."), "What investment risk can early principal repayment create even without a capital loss?", "The investor may need to reinvest sooner at different available terms. Early redemption changes the cash-flow horizon and prevents treating all future coupons as earned."),
        L("Read the final capital barrier", "A European protection barrier is checked at maturity in this example. Above the stated threshold, principal is repaid; below it, the investor bears the contract's downside formula, here linked to the final ratio to initial level. That does not mean losses start only below the barrier as a small deductible. Once the condition fails, the entire specified downside participation applies. Continuous or American-style capital monitoring is another contract. Preserve the equality rule and distinguish a contingent principal repayment from a government or issuer-credit guarantee.", r"R_T=N\left[1-(1-S_T/S_0)^+\mathbf1_{S_T<b_pS_0}\right]", ("Confirm the note survived to maturity rather than autocalling earlier.", "Evaluate the final protection condition under its observation rule.", "Apply the exact principal-loss formula when the condition fails."), "Why can a small move through a capital barrier cause a material redemption change?", "The barrier can switch on the full downside participation formula rather than only a loss measured from the barrier. The term sheet defines the discontinuity."),
        L("Separate receipts from return", "Total cash receipts add paid coupons and principal redemption. Net profit subtracts the original purchase amount and relevant costs, while an annualised return additionally depends on payment dates and reinvestment assumptions. A large principal repayment is not income. The example's returned principal plus memory coupons must not be reported as a one-hundred-and-twelve-percent profit. A cash-flow scenario also does not establish an expected return, because no scenario probabilities were estimated. Report each cash flow with date and condition before summarising an investment outcome.", r"\mathrm{net\ cash\ profit}=\sum_iCF_i-\mathrm{initial\ investment}\quad\text{before costs}", ("List coupons and principal separately at actual settlement dates.", "Subtract initial purchase and disclosed costs for net cash profit.", "Use explicit timing assumptions for any annualised return and avoid an unstated probability claim."), "What is wrong with calling total investor receipts the note's profit?", "Receipts include repayment of the original capital. Profit and return require subtracting the investment, considering timing and costs, and preserving the path conditions."),
        L("Distinguish scenario logic from valuation", "A deterministic path can validate contractual event handling but cannot provide today's fair value without a model over possible future states and appropriate discounting. Volatility, skew, dividends, rates, issuer credit and, for worst-of structures, joint dependence affect valuation. A model can fit vanilla marginals while giving different joint path outcomes for a multi-asset note. Do not replace missing correlation by a decorative matrix. State whether a number is a path cash flow, a simulated model PV or a market indication, and validate the relevant contract before comparing them.", r"V_0=E^Q\!\left[\sum_iDF(0,t_i)CF_i(state, S)\right]", ("Implement the term-sheet state machine on each model path.", "Discount cash flows at the dates they actually occur.", "Average under explicitly specified joint dynamics and include issuer/market conventions as required."), "Does a correct two-observation scenario prove today's note is fairly priced?", "No. It validates one contract path. Valuation needs a distribution of paths, discounting and the relevant market and issuer assumptions."),
        L("Stress discontinuities and issuer risk", "Autocall and protection thresholds can change cash flows abruptly, so test just below, at and above each event boundary. A down market with higher volatility can change both early-call probability and tail principal exposure. Issuer default can impair repayment even when the market-linked protection condition is satisfied. A note's embedded options and its unsecured issuer claim are different risk mechanisms. Do not describe contingent capital protection as an unconditional guarantee. A useful stress memo identifies which contractual state and which credit assumption drive the loss.", r"\mathrm{note\ risk}=\mathrm{market\ linked\ cash\ flows}+\mathrm{issuer\ exposure}", ("Test each threshold with explicit equality and observation rules.", "Apply adverse market paths and identify coupon, call and capital-state changes.", "Assess issuer and liquidity risk separately from the market-linked payoff formula."), "Can a satisfied capital-protection condition eliminate issuer default risk?", "No. It specifies a promised contractual redemption under market conditions. The issuer's ability and obligation to pay remain separate credit considerations."),
        L("Check a worst-of extension", "A worst-of feature takes a minimum across reference performances and changes dependence sensitivity. Its probability of coupon or call events cannot be reconstructed from each asset's marginal volatility alone. Initial levels, corporate actions, correlation dynamics and asynchronous fixing rules matter. A single-index template must reject or explicitly defer this extension rather than quietly reuse the same payoff. A correlation stress is a conditional model experiment, not a historical certainty. Preserve the exact asset basket and joint-model assumptions in both numerical validation and the desk explanation.", r"W_i=\min_j\frac{S_{j,t_i}}{S_{j,0}}", ("Normalise each reference asset to its own initial fixing.", "Apply the minimum performance at the contractual observation.", "Use explicitly modelled joint paths and validate how dependence changes event probabilities."), "Can the single-index worked scenario determine a worst-of autocall price?", "No. It lacks a basket and joint path model. The extension requires additional contract definitions and dependence assumptions, not a relabelled output."),
        L("Write a defensible term-sheet memo", "The memo should reconstruct the event sequence, memory balance, coupon payments, principal redemption and termination date. Explain total receipts and net investment profit separately. State the scenario's conditional nature and the unmodelled issuer, liquidity or joint-market risks. If asked for a commercial sale or valuation, request the complete legal terms and appropriate model rather than relying on the illustration. A candidate adds value by finding a state-machine mistake or an unsupported guarantee before presenting an attractive coupon figure.", r"\mathrm{memo}=(\mathrm{terms},\mathrm{path},\mathrm{state\ history},CF,\mathrm{limits})", ("Reconcile each cash flow with its event and observation date.", "Separate principal, coupon, net profit and annualisation.", "Explain the adverse state and propose validation or escalation before a quote."), "Which warning is essential when presenting the memory-coupon example?", "It is a conditional cash-flow scenario, not a guaranteed yield or a current fair value. Early redemption and downside/issuer risks remain material in other states."),
    ),
    (
        ("What must happen after an eligible autocall redeems the note?", "Stop subsequent contractual observations and future coupon accrual under the terminated note.", ("Continue paying every remaining scheduled coupon.", "Reset initial spot and issue a free replacement note.", "Apply the final protection formula again at the old maturity.", "Treat redeemed principal as pure investment profit."), "Autocall is a state transition that terminates the note. Cash flows already due at redemption follow the actual terms, but later events must not be double counted."),
        ("What does a memory feature do in the supplied coupon scenario?", "It stores missed contractual coupons and releases them when the stated eligible condition is met.", ("It guarantees every coupon regardless of future conditions.", "It automatically compounds missed coupons at the stock return.", "It converts a per-observation rate into a guaranteed annual yield.", "It eliminates issuer and principal-loss risk."), "Memory is a specific cash-flow rule. It does not remove conditions, determine probabilities or guarantee investment performance."),
        ("How should total receipts of principal and coupons be interpreted?", "They include returned capital; net profit also subtracts initial investment and relevant costs.", ("They are all profit without any deduction.", "They establish an expected return without scenario probabilities.", "They are automatically annualised regardless of dates.", "They certify current fair value."), "Cash receipts, profit, return and present value answer different questions. Preserve payment timing and conditions."),
        ("What does an intact market-linked capital-protection condition fail to guarantee?", "The issuer's ability to pay or the absence of liquidity and credit risk.", ("A contractual principal amount under the specified market condition.", "The need to identify the final observation rule.", "The existence of the stated coupon threshold.", "The fact that the note has a legal issuer."), "A promised payoff and a risk-free payment are different. Issuer exposure remains even if the market condition for redemption is met."),
        ("What is required to extend this single-index illustration to a worst-of note valuation?", "Exact basket terms and a validated joint-path/dependence model in addition to marginal inputs.", ("Only changing the product title.", "A decorative correlation chart without numerical assumptions.", "Adding the standalone asset prices without an event model.", "Assuming all future coupons are paid before simulating."), "Worst-of event probabilities depend on joint behaviour and contractual fixings. A correct single-index path does not validate that extension."),
    ),
)

VAR = Course(
    "market-risk-var-stress", "var", "Market risk: VaR, expected shortfall and stress decisions", "zero-mean Gaussian portfolio loss benchmark",
    "parametric_var", "Parametric VaR portfolio 20m daily volatility 2% confidence 95% horizon 1 day.",
    "Quantiles, normal distributions, standard deviation, covariance, portfolio returns and a positive-loss sign convention.",
    "Tail misspecification, nonlinear positions, changing dependence, liquidity and loss beyond the quantile. A VaR limit is not a maximum possible loss or a statement that tail events cannot occur.",
    "Zero-mean Gaussian returns with stated daily volatility and horizon, constant exposure and square-root-of-time scaling only under its assumptions. VaR and ES are benchmark loss amounts, not a full historical/filtered risk system, regulatory capital measure or live risk approval.",
    "mc",
    (
        L("Define loss, horizon and confidence", "VaR is a quantile of a specified loss distribution over a defined horizon. Decide whether positive numbers represent losses or profits before reading a percentile. Confidence, horizon, portfolio state and data/measure assumptions are part of the statistic. A one-day 95% VaR is not a prediction of the next day's realised loss and not a maximum loss. Different sign conventions can reverse which tail is examined. Preserve the valuation date, positions and treatment of cash flows so a risk number corresponds to an actual portfolio rather than a floating screen label.", r"VaR_\alpha(L)=\inf\{l:P(L\le l)\ge\alpha\}", ("Define portfolio loss with a consistent positive-loss sign.", "Specify horizon, confidence and the distributional model.", "Read the corresponding quantile without interpreting it as a loss cap."), "What can happen beyond a stated 95% VaR threshold?", "Larger losses remain possible in the tail. Their frequency and severity depend on the model; VaR alone does not describe how large those losses can be."),
        L("Derive the Gaussian benchmark", "Under zero-mean normal portfolio returns and a locally linear fixed exposure, the loss standard deviation is market value times return volatility. Multiplying by the normal confidence quantile gives the benchmark VaR. If mean or nonlinear exposure matters, the expression must be adapted rather than silently reused. Convert volatility into the same horizon unit as the loss distribution. The calculation is transparent and useful as a scale control, but Gaussian tails can understate jump and crisis losses. A correct normal quantile does not validate the distributional assumption.", r"VaR_\alpha=V\sigma_h z_\alpha", ("Map a portfolio return into a positive-loss currency variable.", "Use the zero-mean Gaussian loss standard deviation V times horizon volatility.", "Multiply by the stated normal quantile and attach currency and horizon."), "Why is daily volatility times an annual horizon without conversion invalid?", "The time units differ. Convert under explicit scaling assumptions or use a model/data estimate for the actual target horizon."),
        L("Derive expected shortfall", "Expected shortfall summarises average loss in the tail beyond a quantile, with the appropriate definition for distributions containing atoms. For a continuous normal loss distribution, integrating the tail yields normal density at the confidence quantile divided by tail probability. ES therefore contains information about tail severity that VaR alone lacks. Its coherence under standard conditions does not make it immune to model error or unstable tail estimation. A sample with few tail observations can make an apparently precise ES unreliable. Report the model and available tail evidence alongside the number.", r"ES_\alpha=V\sigma_h\frac{\phi(z_\alpha)}{1-\alpha}\quad\text{(continuous Gaussian)}", ("Condition the continuous loss variable on exceeding its alpha quantile.", "Integrate the Gaussian tail using the normal density identity.", "Divide by tail probability and scale by portfolio loss standard deviation."), "Why is ES useful even when the VaR confidence level is known?", "It describes average loss severity within the modelled tail. VaR gives the threshold, not the size of losses beyond it."),
        L("Use time scaling only under assumptions", "Square-root-of-time scaling assumes an aggregation structure such as independent, identically distributed zero-mean increments with stable variance and a sufficiently linear exposure. Volatility clustering, autocorrelation, jumps, position changes and nonlinear payoffs can invalidate a simple horizon multiplier. A ten-day VaR is not automatically a one-day number times square root of ten for every portfolio. State what is held fixed and compare a direct horizon model where possible. Horizon conversion is a modelling step, not a unit conversion that can be applied without economic assumptions.", r"\sigma_h=\sigma_1\sqrt h\quad\text{under iid stable-variance increments}", ("Identify the base volatility time unit and desired loss horizon.", "State independence, variance stability and exposure assumptions.", "Scale only within that model and assess a direct horizon alternative for nonlinear or dependent risks."), "What breaks naive square-root scaling for an options portfolio?", "Changing deltas/gammas, path effects, volatility dynamics and other nonlinearities can alter horizon loss aggregation. The iid linear benchmark is conditional."),
        L("Aggregate risk through covariance", "Portfolio variance depends on exposures, volatilities and their dependence, not the sum of standalone volatilities. A covariance matrix must be symmetric and positive semidefinite to define coherent variance for every weight vector. Estimated correlations can change in stress, and a small variance under one historical regime may hide concentrated tail events. Different signed positions can create cancellation under a parallel factor move without eliminating basis or nonlinear risk. State the factor map and units before multiplying a matrix. Correlation is neither causation nor a complete description of joint tail behaviour.", r"\sigma_P^2=w^\top\Sigma w", ("Map signed exposures into consistent factor-return coordinates.", "Construct a symmetric positive-semidefinite covariance estimate.", "Compute portfolio variance and examine dependence and concentration stresses separately."), "Why is adding two standalone VaRs generally not an exact portfolio VaR?", "The portfolio loss distribution depends on joint behaviour and positions. Dependence and nonlinear aggregation determine the actual quantile; VaR is not generally subadditive."),
        L("Separate stress tests from probabilities", "A stress test specifies a plausible or severe configuration of market moves and asks what it does to the portfolio. It need not claim a calibrated probability. Historical scenarios are informative but do not exhaust possible future states, while hypothetical scenarios should state the economic mechanism and input changes. Use consistent full repricing when linear approximations become inadequate. A large stress loss and a modest Gaussian VaR can coexist because the calculations answer different questions. Preserve both rather than adjusting a stress until it agrees with a convenient limit metric.", r"L_{stress}=V_{before}-V_{after\ scenario}\quad\text{on a consistent basis}", ("Specify factor shocks, held-fixed inputs and any event transitions.", "Revalue the same positions consistently under the scenario.", "Report loss and mechanism without inventing a scenario probability."), "Does a severe scenario loss contradict a smaller 95% Gaussian VaR?", "Not necessarily. A quantile under a model and a conditional stress answer different questions. The difference can expose an important model limitation."),
        L("Backtest a risk forecast without hindsight", "A VaR backtest compares forecasts made before the horizon with realised P&L on the appropriate portfolio basis. Actual and hypothetical P&L can differ because positions and costs change. Exceptions are not automatically model failures, but their frequency, clustering and severity require investigation. A short sample has limited statistical power. Do not refit using future outcomes and then describe the result as an independent forecast test. Retain the original forecasts, timestamps, portfolio definitions and exception decisions for reproducible review.", r"I_t=\mathbf1_{L_t>VaR_{\alpha,t-1}}", ("Preserve the risk forecast available before the realised horizon.", "Compare with consistently defined actual or hypothetical P&L.", "Assess exception frequency, dependence and severity without look-ahead refitting."), "Why do a few exceptions not by themselves prove a 95% VaR model is wrong?", "Exceptions are expected under the stated confidence model. Sample size, clustering, severity and forecast/P&L alignment determine what can be inferred."),
        L("Act on limits and explain uncertainty", "A limit comparison requires an actual approved threshold, not a number invented to make the dashboard green. State which metric and horizon the limit governs. A breach can require escalation, hedging or exposure reduction even when its statistical interpretation is uncertain. Identify the largest risk drivers and how a proposed hedge changes both ordinary and stressed outcomes. Keep approval roles and operational actions distinct from a teaching calculation. A risk report should explain tail and model limitations rather than imply the chosen confidence level makes the remaining loss acceptable.", r"\mathrm{usage}=\frac{\mathrm{risk\ metric}}{\mathrm{approved\ comparable\ limit}}", ("Match metric, currency, horizon and confidence to the actual limit definition.", "Identify the exposure and scenarios driving a breach.", "Escalate or propose a bounded hedge with explicit residual and model risks."), "Can the benchmark risk number alone certify a position is within approved limits?", "No. It needs an actual comparable limit and governance context. The teaching example does not invent approval or claim an official risk decision."),
        L("Write the tail-risk memo", "A concise memo identifies the portfolio, loss sign, confidence, horizon, model and data basis before reporting VaR and ES. Add at least one informative stress and distinguish its conditional result from a probability forecast. State where Gaussian, linearity or scaling assumptions could fail and what additional evidence would improve the assessment. If a limit is missing, say so instead of reporting a passing status. The recommended action should target the risk mechanism, and the report should preserve original inputs and forecasts for later review.", r"\mathrm{memo}=(VaR,ES,\mathrm{stress},\mathrm{assumptions},\mathrm{limit\ status})", ("Reconcile currency, horizon and positive-loss conventions.", "Present the quantile, tail mean and stress as distinct deliverables.", "Recommend monitor, hedge, reduce or escalate according to verified evidence and authority."), "What makes the benchmark numbers useful without pretending they validate the market distribution?", "Their assumptions and reproducible formulas give a transparent scale control. Tail, nonlinear and data limitations remain explicit and can guide further validation."),
    ),
    (
        ("What does a one-day 95% VaR describe?", "A loss quantile under the stated one-day distribution and portfolio conventions.", ("The maximum loss that can ever occur.", "A guarantee of profit on ninety-five percent of days.", "The mean of all future losses regardless of confidence.", "An approved trading limit without a supplied threshold."), "VaR is conditional on model, horizon and portfolio. Losses beyond its threshold remain possible and can be large."),
        ("What extra feature does continuous-distribution ES describe beyond VaR?", "Average loss severity in the tail beyond the confidence quantile.", ("Only the colour of a limit indicator.", "The actual future worst loss with certainty.", "An absence of estimation error because ES is coherent.", "A physical probability supplied by any chosen stress scenario."), "ES adds tail-severity information but still depends on a distribution and sufficient tail evidence. Coherence is not empirical certainty."),
        ("When is square-root-of-time scaling a justified benchmark?", "Under explicit stable-variance, aggregation and exposure assumptions such as iid linear increments.", ("For every nonlinear portfolio under every regime.", "Because time scaling is always a convention-free unit conversion.", "Whenever a historical chart looks smooth.", "Only after changing the portfolio to match the desired answer."), "The scaling law is a modelling result. Dependence, changing volatility, jumps and nonlinear exposure can require another horizon model."),
        ("What does a hypothetical stress require before its loss can be interpreted?", "Declared shocks, held-fixed assumptions and a consistent valuation of the same positions.", ("A made-up probability inferred from the number of table rows.", "Agreement with the Gaussian VaR by construction.", "Deletion of scenarios that exceed a preferred limit.", "A guarantee that historical correlations persist in crisis."), "A stress is a conditional mechanism test. Probabilities require separate modelling and evidence, while repricing conventions determine comparability."),
        ("What is needed before declaring a calculated VaR within limit?", "An actual comparable approved limit and the relevant metric/horizon definition.", ("A default passing status whenever a calculator returns a number.", "An invented threshold set just above the result.", "Only a positive portfolio notional.", "No consideration of tail or stress risk."), "Risk calculation and approval are distinct. Missing governance inputs must remain unavailable rather than becoming a fabricated green result."),
    ),
)

COURSES = {course.key: course for course in (VANILLA, GREEKS, SWAP, CURVE, BOND, SMILE, MONTE, STOCHASTIC, BARRIER, CDS, AUTOCALL, VAR)}
